window.MG_LAZY_DATA["data/lazy/owner-courses/b329-6eb7d29ed3a2d2b8.json"]={sha256:"6eb7d29ed3a2d2b87484aebf1e73c1e11b7548ff2f86bf4bdff2d36d7ff262a0",value:{"id":"b329","title":"紐約第二大道地鐵一期","titleEn":"Second Avenue Subway Phase 1","category":"rail","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","summary":"以紐約第二大道地鐵一期為背景，建立密集街廓下方新站與既有線銜接的教學剖面。課程把測量、灌漿、施工時間窗口及乘客垂直交通結合，要求分開施工變形控制和營運期人流驗證，並保留不確定度。","summaryEn":"Use Second Avenue Subway Phase 1 to construct a teaching section with new stations beneath dense city blocks and a connection to an existing line. Combine surveying, grouting, possession windows and vertical passenger movement. Keep construction-movement control distinct from operational passenger-flow validation, and retain uncertainty rather than treating one instrument reading as a complete statement about building or station performance.","scope":"依公開工程原理、官方資料與規範架構編寫的原創教學；步驟是可驗證的學習任務與假想算例，不是設計圖說、施工計畫、軌道進入、牽引供電隔離或列車營運許可，也不是任何專案的設計文件。數值均為教學假設或公開資料，實際工程須由合格技師依規範與實測資料重新計算並簽證。","scopeEn":"Original teaching built from public engineering principles, official sources and code frameworks. Steps are verifiable learning tasks and hypothetical exercises, not design drawings, method statements, track-access, traction-power isolation or train-operation permits, or any project's design documents. Numbers are teaching assumptions or public data; real work must be recalculated and certified by qualified engineers using codes and measured data.","subcategory":"rail-metro","subcategoryTitle":"都會捷運與貨運","subcategoryTitleEn":"Urban metros and freight","learningTrack":"rail","learningSubdiscipline":"rail-metro","learningTags":["rail","rail-metro","station"],"architectureFamily":"rail-system","architectureNodes":[["路線與土建","Alignment and civil works"],["車輛與接觸","Vehicle and contact"],["牽引供電","Traction supply"],["行車控制","Movement control"],["車站與旅客","Stations and passengers"],["監測與維護","Monitoring and maintenance"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,1],[3,4],[4,5],[5,0],[5,3]],"diagram":{"type":"rail-system","labels":["路線與土建","車輛與接觸","牽引供電","行車控制","車站與旅客"],"labelsEn":["Alignment and civil works","Vehicle and contact","Traction supply","Movement control","Stations and passengers"],"original":true,"notToScale":true},"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"整合原創算例：單元 1 得 residual=5 mm；單元 2 得 gradient=0.6 mm/m；單元 3 得 grout_volume=2.3 m^3。上述三個結果使用各單元明示的不同邊界，不能任意相加或視為實際工程實測值。以第一單元 dx 的擾動測試，結果改為 5.185557 mm；學徒需先比較單位、敏感度和假設，再決定是否要細化模型。以紐約第二大道地鐵一期為背景，建立密集街廓下方新站與既有線銜接的教學剖面。課程把測量、灌漿、施工時間窗口及乘客垂直交通結合，要求分開施工變形控制和營運期人流驗證，並保留不確定度。 最終交付應保留原始輸入、測點時間戳、誤差範圍與無法由簡化式證明的結論。","textEn":"Integrated original exercise: unit 1 gives residual=5 mm; unit 2 gives gradient=0.6 mm/m; unit 3 gives grout_volume=2.3 m^3. These three results use different explicit boundaries and must not be added or presented as measurements of the real railway. Perturbing dx in the first unit changes its result to 5.185557 mm. Compare units, sensitivity and assumptions before deciding which model needs refinement. Use Second Avenue Subway Phase 1 to construct a teaching section with new stations beneath dense city blocks and a connection to an existing line. Combine surveying, grouting, possession windows and vertical passenger movement. Keep construction-movement control distinct from operational passenger-flow validation, and retain uncertainty rather than treating one instrument reading as a complete statement about building or station performance. The final submission should retain original inputs, measurement timestamps, uncertainty ranges and conclusions that the simplified expressions cannot establish.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"depth":5,"languageCoverage":["zh-TW","en"],"simulationOnly":true,"educationEdition":16,"enrichmentVersion":16,"stages":[{"id":"b329-v16-s1","title":"控制網與獨立量測殘差與沉陷差與軌道坡折","titleEn":"Survey control and independent residuals & Differential settlement and track kink","description":"本階段聚焦「控制網與獨立量測殘差」與「沉陷差與軌道坡折」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Survey control and independent residuals\" and \"Differential settlement and track kink\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b329-v16-01","title":"控制網與獨立量測殘差：機制與系統路徑","titleEn":"Survey control and independent residuals: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":[],"objective":"說明「控制網與獨立量測殘差」如何影響紐約第二大道地鐵一期的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Survey control and independent residuals” governs forces, deformation, flow or signals in “Second Avenue Subway Phase 1”, and map the relevant inputs, transfer paths and boundaries.","instruction":"兩套獨立量測可用座標差的平方和開根號描述平面殘差，但這只是對照量而不是絕對準確度。共同基點錯誤會同時影響兩套結果，控制網需要閉合檢查及外部基準才能發現系統偏差。 兩座標差的歐氏長度表示平面殘差大小，不是隨機標準差。先把兩套座標轉到相同基準和單位，再檢查各方向偏差；共同平移可能讓相對殘差很小但絕對位置仍錯。 對街區水準測量做閉合檢核並以穩定外部基準控制漂移。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「控制網與獨立量測殘差」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"The root-sum-square of coordinate differences describes planar residual between independent measurements, not absolute accuracy. A shared control-point error affects both results. Network closure and an external datum are needed to reveal systematic bias that agreement alone can conceal. The Euclidean length of two coordinate differences measures planar residual, not random standard deviation. Transform both coordinate sets to one datum and unit before inspecting directional differences. Common translation can leave a small relative residual while absolute position remains wrong. Check closure in block-level levelling and control drift against a stable external datum. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Survey control and independent residuals” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：dx=0.003 m; dy=0.004 m；計算：residual=(dx*dx+dy*dy)**0.5*1000=5 mm。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: dx=0.003 m; dy=0.004 m; calculation: residual=(dx*dx+dy*dy)**0.5*1000=5 mm.","failure":"常見誤解：「兩台儀器量得同樣座標就證明座標絕對正確」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Matching coordinates from two instruments prove absolute coordinate accuracy.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「控制網與獨立量測殘差」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Survey control and independent residuals”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b329-v16-01-k1","title":"控制網與獨立量測殘差","titleEn":"Survey control and independent residuals","text":"兩套獨立量測可用座標差的平方和開根號描述平面殘差，但這只是對照量而不是絕對準確度。共同基點錯誤會同時影響兩套結果，控制網需要閉合檢查及外部基準才能發現系統偏差。","textEn":"The root-sum-square of coordinate differences describes planar residual between independent measurements, not absolute accuracy. A shared control-point error affects both results.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：兩台儀器量得同樣座標就證明座標絕對正確 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Matching coordinates from two instruments prove absolute coordinate accuracy. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"關於「控制網與獨立量測殘差」，下列哪一項敘述正確？","questionEn":"Which statement about \"Survey control and independent residuals\" is correct?","options":["兩台儀器量得同樣座標就證明座標絕對正確","兩套獨立量測可用座標差的平方和開根號描述平面殘差，但這只是對照量而不是絕對準確度。","兩端高程相同就能證明兩點之間沒有差異沉陷"],"optionsEn":["Matching coordinates from two instruments prove absolute coordinate accuracy.","The root-sum-square of coordinate differences describes planar residual between independent measurements, not absolute accuracy.","Equal endpoint elevations prove there is no differential settlement between them."],"answer":1,"explanation":"兩套獨立量測可用座標差的平方和開根號描述平面殘差，但這只是對照量而不是絕對準確度。 其餘選項是常見誤解。","explanationEn":"The root-sum-square of coordinate differences describes planar residual between independent measurements, not absolute accuracy. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":1},{"id":"b329-v16-02","title":"控制網與獨立量測殘差：定量估算","titleEn":"Survey control and independent residuals: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-01"],"objective":"以數值模型估算「控制網與獨立量測殘差」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Survey control and independent residuals” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：dx=0.003 m; dy=0.004 m；計算：residual=(dx*dx+dy*dy)**0.5*1000=5 mm。敏感度：dx 單獨增加百分之十至 0.0033 m，其餘固定，結果為 5.185557 mm。模型邊界：平面兩分量殘差；不含座標轉換協方差和垂直誤差。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: dx=0.003 m; dy=0.004 m; calculation: residual=(dx*dx+dy*dy)**0.5*1000=5 mm. Sensitivity: dx, increase this input alone by ten percent, to 0.0033 m, with all other inputs fixed, gives 5.185557 mm. Model boundary: Planar two-component residual; transformation covariance and vertical error are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。","observationEn":"How to cross-check: Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b329-v16-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：dx=0.003 m; dy=0.004 m；計算：residual=(dx*dx+dy*dy)**0.5*1000=5 mm。敏感度：dx 單獨增加百分之十至 0.0033 m，其餘固定，結果為 5.185557 mm。模型邊界：平面兩分量殘差；不含座標轉換協方差和垂直誤差。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: dx=0.003 m; dy=0.004 m; calculation: residual=(dx*dx+dy*dy)**0.5*1000=5 mm. Sensitivity: dx, increase this input alone by ten percent, to 0.0033 m, with all other inputs fixed, gives 5.185557 mm. Model boundary: Planar two-component residual; transformation covariance and vertical error are excluded.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"依「控制網與獨立量測殘差」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Survey control and independent residuals\", which statement holds?","options":["施工窗口全長都可以直接乘以施工速度當成可完成量","風機已經啟動就能證明隧道每一處濃度同樣下降","原創假想算例，全部輸入均非本工程操作參數：dx=0.003 m; dy=0.004 m。"],"optionsEn":["The entire possession duration can be multiplied by work rate to obtain achievable production.","A running fan proves concentration falls equally at every point in the tunnel.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：dx=0.003 m; dy=0.004 m；計算：residual=(dx*dx+dy*dy)**0.5*1000=5 mm。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: dx=0.003 m; dy=0.004 m; calculation: residual=(dx*dx+dy*dy)**0.5*1000=5 mm. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":2},{"id":"b329-v16-03","title":"控制網與獨立量測殘差：試驗與驗證","titleEn":"Survey control and independent residuals: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「控制網與獨立量測殘差」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Survey control and independent residuals” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。 以反向觀測、閉合路線和外部基準交叉檢核，分開報告平面殘差與可疑共同偏差。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias. Cross-check reversed observations, closed loops and external references, reporting planar residual separately from suspected shared bias. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：加入一個共同平移偏差，檢查兩儀器殘差與外部基準差異，提出能辨識系統誤差的控制網配置。 再以本單元 dx 的對照值重算 residual，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Add a shared translation bias, compare inter-instrument residual with error to an external datum, and propose a control network that can reveal systematic error. Also recalculate residual for the alternative dx value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b329-v16-03-k1","title":"驗證方法","titleEn":"Verification method","text":"用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。 以反向觀測、閉合路線和外部基準交叉檢核，分開報告平面殘差與可疑共同偏差。","textEn":"Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias. Cross-check reversed observations, closed loops and external references, reporting planar residual separately from suspected shared bias.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-03-k2","title":"現場實務","titleEn":"Site practice","text":"加入一個共同平移偏差，檢查兩儀器殘差與外部基準差異，提出能辨識系統誤差的控制網配置。 再以本單元 dx 的對照值重算 residual，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Add a shared translation bias, compare inter-instrument residual with error to an external datum, and propose a control network that can reveal systematic error. Also recalculate residual for the alternative dx value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"要驗證「控制網與獨立量測殘差」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Survey control and independent residuals\"?","options":["用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。","量測時不必記錄溫度、速度、運行歷程與施工荷重，因為它們不會影響結果。","排水管截面夠大就不需要檢查入口堵塞及下游水位"],"optionsEn":["Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias.","Temperature, speed, operating history and construction loads need not be recorded because they cannot affect the result.","A sufficiently large drain eliminates the need to check blocked inlets and tailwater."],"answer":0,"explanation":"用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":3},{"id":"b329-v16-04","title":"控制網與獨立量測殘差：失效診斷","titleEn":"Survey control and independent residuals: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-03"],"objective":"從症狀倒推「控制網與獨立量測殘差」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Survey control and independent residuals” and propose discriminating checks, corrective actions and prevention.","instruction":"同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。 閉合良好仍可能全部同向漂移，須使用外部穩定基準。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error. Good closure can coexist with common drift; an external stable reference remains necessary. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：對街區水準測量做閉合檢核並以穩定外部基準控制漂移。","observationEn":"Link to the mechanism: Check closure in block-level levelling and control drift against a stable external datum.","failure":"誤判風險：若相信「兩台儀器量得同樣座標就證明座標絕對正確」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Matching coordinates from two instruments prove absolute coordinate accuracy.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b329-v16-04-k1","title":"失效模式","titleEn":"Failure mode","text":"同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。 閉合良好仍可能全部同向漂移，須使用外部穩定基準。","textEn":"One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error. Good closure can coexist with common drift; an external stable reference remains necessary.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"在「控制網與獨立量測殘差」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Survey control and independent residuals\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。","兩端高程相同就能證明兩點之間沒有差異沉陷"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error.","Equal endpoint elevations prove there is no differential settlement between them."],"answer":1,"explanation":"同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。 需以量測區分可能原因。","explanationEn":"One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":4},{"id":"b329-v16-05","title":"沉陷差與軌道坡折：機制與系統路徑","titleEn":"Differential settlement and track kink: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-04"],"objective":"說明「沉陷差與軌道坡折」如何影響紐約第二大道地鐵一期的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Differential settlement and track kink” governs forces, deformation, flow or signals in “Second Avenue Subway Phase 1”, and map the relevant inputs, transfer paths and boundaries.","instruction":"均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。兩端高差除以基長只給平均坡度，無法描述局部尖峰；需要多點剖面才能辨認曲率與變形長度。 相同端點坡度可以對應完全不同的中間形狀，因此坡度不能單獨表示軌道曲率。測點間距必須小於欲辨認的變形尺度，並將高程誤差相對於基長傳遞到坡度結果。 將建築兩端高差與中間沉陷槽分開，檢查測點密度。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「沉陷差與軌道坡折」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading. End-to-end difference divided by baseline gives only an average gradient, not a local peak. A spatial profile is needed to identify curvature and deformation length. Identical endpoint gradient can hide very different intermediate shapes, so gradient alone cannot describe track curvature. Survey spacing must resolve the deformation length scale, and elevation uncertainty must be propagated relative to the baseline into the reported gradient. Separate end-to-end building difference from an intermediate trough and inspect point spacing. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Differential settlement and track kink” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：drop=0.012 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.6 mm/m。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.012 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.6 mm/m.","failure":"常見誤解：「兩端高程相同就能證明兩點之間沒有差異沉陷」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Equal endpoint elevations prove there is no differential settlement between them.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「沉陷差與軌道坡折」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Differential settlement and track kink”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b329-v16-05-k1","title":"沉陷差與軌道坡折","titleEn":"Differential settlement and track kink","text":"均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。兩端高差除以基長只給平均坡度，無法描述局部尖峰；需要多點剖面才能辨認曲率與變形長度。","textEn":"Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading. End-to-end difference divided by baseline gives only an average gradient, not a local peak.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：兩端高程相同就能證明兩點之間沒有差異沉陷 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Equal endpoint elevations prove there is no differential settlement between them. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"關於「沉陷差與軌道坡折」，下列哪一項敘述正確？","questionEn":"Which statement about \"Differential settlement and track kink\" is correct?","options":["兩端高程相同就能證明兩點之間沒有差異沉陷","注入漿量超過幾何空隙體積就能證明沒有殘留空洞","均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。"],"optionsEn":["Equal endpoint elevations prove there is no differential settlement between them.","Injecting more than the geometric void volume proves that no void remains.","Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading."],"answer":2,"explanation":"均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。 其餘選項是常見誤解。","explanationEn":"Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":5},{"id":"b329-v16-06","title":"沉陷差與軌道坡折：定量估算","titleEn":"Differential settlement and track kink: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-05"],"objective":"以數值模型估算「沉陷差與軌道坡折」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Differential settlement and track kink” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：drop=0.012 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.6 mm/m。敏感度：drop 單獨增加百分之十至 0.0132 m，其餘固定，結果為 0.66 mm/m。模型邊界：小變形平均坡度；不計車軌耦合動力或容許軌道幾何。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.012 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.6 mm/m. Sensitivity: drop, increase this input alone by ten percent, to 0.0132 m, with all other inputs fixed, gives 0.66 mm/m. Model boundary: Small-deformation average gradient; vehicle-track dynamics and permissible geometry limits are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。","observationEn":"How to cross-check: Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b329-v16-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：drop=0.012 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.6 mm/m。敏感度：drop 單獨增加百分之十至 0.0132 m，其餘固定，結果為 0.66 mm/m。模型邊界：小變形平均坡度；不計車軌耦合動力或容許軌道幾何。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.012 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.6 mm/m. Sensitivity: drop, increase this input alone by ten percent, to 0.0132 m, with all other inputs fixed, gives 0.66 mm/m. Model boundary: Small-deformation average gradient; vehicle-track dynamics and permissible geometry limits are excluded.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"依「沉陷差與軌道坡折」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Differential settlement and track kink\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：drop=0.012 m; baseline=20 m。","兩台電扶梯的實際總輸送率必定等於單台額定值兩倍","只要月台平均密度低就不會在任何局部出現壅塞"],"optionsEn":["Original hypothetical exercise.","Two escalators necessarily deliver twice the rated throughput of one escalator.","Low average platform density prevents congestion at every local point."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：drop=0.012 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.6 mm/m。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.012 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.6 mm/m. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":6},{"id":"b329-v16-07","title":"沉陷差與軌道坡折：試驗與驗證","titleEn":"Differential settlement and track kink: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「沉陷差與軌道坡折」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Differential settlement and track kink” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。 重複觀測同一測點並做閉合檢核，以另一穩定基準核對零點，報告高差與基長各自誤差。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift. Repeat identical points with closure checks, verify zero against another stable reference, and report separate errors for elevation difference and baseline. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：構造端點相同但中間下陷的剖面，與直線坡度模型比較；提出足以辨識沉陷槽寬度的測點間距與複測頻率。 再以本單元 drop 的對照值重算 gradient，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Construct a profile with equal endpoints and an intermediate trough, compare it with a straight-gradient model, and propose spacing and repeat intervals able to resolve the trough. Also recalculate gradient for the alternative drop value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b329-v16-07-k1","title":"驗證方法","titleEn":"Verification method","text":"採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。 重複觀測同一測點並做閉合檢核，以另一穩定基準核對零點，報告高差與基長各自誤差。","textEn":"Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift. Repeat identical points with closure checks, verify zero against another stable reference, and report separate errors for elevation difference and baseline.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-07-k2","title":"現場實務","titleEn":"Site practice","text":"構造端點相同但中間下陷的剖面，與直線坡度模型比較；提出足以辨識沉陷槽寬度的測點間距與複測頻率。 再以本單元 drop 的對照值重算 gradient，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Construct a profile with equal endpoints and an intermediate trough, compare it with a straight-gradient model, and propose spacing and repeat intervals able to resolve the trough. Also recalculate gradient for the alternative drop value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"要驗證「沉陷差與軌道坡折」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Differential settlement and track kink\"?","options":["沿用另一處鐵路設施或路線的量測結果，就可視為本工程已完成驗證。","採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。","聯鎖只要正常路徑通過測試就不需要檢查衝突請求"],"optionsEn":["Reusing results from another railway facility or route counts as verifying this structure.","Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift.","Passing normal route tests removes the need to test conflicting requests."],"answer":1,"explanation":"採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":7},{"id":"b329-v16-08","title":"沉陷差與軌道坡折：失效診斷","titleEn":"Differential settlement and track kink: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-07"],"objective":"從症狀倒推「沉陷差與軌道坡折」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Differential settlement and track kink” and propose discriminating checks, corrective actions and prevention.","instruction":"基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 高差異常需先查基點，不能立刻推定路基局部下沉。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. An unusual level difference requires a datum check before inferring local earthwork settlement. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：將建築兩端高差與中間沉陷槽分開，檢查測點密度。","observationEn":"Link to the mechanism: Separate end-to-end building difference from an intermediate trough and inspect point spacing.","failure":"誤判風險：若相信「兩端高程相同就能證明兩點之間沒有差異沉陷」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Equal endpoint elevations prove there is no differential settlement between them.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b329-v16-08-k1","title":"失效模式","titleEn":"Failure mode","text":"基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 高差異常需先查基點，不能立刻推定路基局部下沉。","textEn":"A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. An unusual level difference requires a datum check before inferring local earthwork settlement.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"在「沉陷差與軌道坡折」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Differential settlement and track kink\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","注入漿量超過幾何空隙體積就能證明沒有殘留空洞","基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Injecting more than the geometric void volume proves that no void remains.","A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact."],"answer":2,"explanation":"基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 需以量測區分可能原因。","explanationEn":"A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":8}],"order":1},{"id":"b329-v16-s2","title":"注漿量與空隙體積與施工窗口與可完成工作量","titleEn":"Grout volume and void account & Possession window and achievable work","description":"本階段聚焦「注漿量與空隙體積」與「施工窗口與可完成工作量」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Grout volume and void account\" and \"Possession window and achievable work\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b329-v16-09","title":"注漿量與空隙體積：機制與系統路徑","titleEn":"Grout volume and void account: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-08"],"objective":"說明「注漿量與空隙體積」如何影響紐約第二大道地鐵一期的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Grout volume and void account” governs forces, deformation, flow or signals in “Second Avenue Subway Phase 1”, and map the relevant inputs, transfer paths and boundaries.","instruction":"填充空隙所需漿量先由幾何空隙體積估算，再考慮損失與材料體積變化。注入量大不代表填充完整，因為漿液可能沿裂縫流失；壓力、流量與返漿紀錄必須互相對照。 此算例把空隙視為長乘寬乘均勻厚度的薄層，再乘假定餘量。它不是完整圓環幾何；若用於環隙局部展開，須說明薄層近似，且不能由注入總量推論填充均勻。 用局部薄層幾何估算漿量，另外記錄超灌與回流來源。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「注漿量與空隙體積」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Required grout begins with geometric void volume and allowances for loss and volume change. A large injected volume does not prove complete filling because grout can escape through cracks. Pressure, flow and returns must be interpreted together to distinguish filling from loss. This example treats a void as length times width times uniform thickness with an assumed allowance. It is not full annular geometry. A locally unwrapped annulus requires an explicit thin-layer approximation, and total injection does not establish uniform filling. Estimate grout volume from local thin-layer geometry and separately record excess injection and returns. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Grout volume and void account” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：length=20 m; width=2.5 m; gap=0.04 m; allowance=1.15 1；計算：grout_volume=length*width*gap*allowance=2.3 m^3。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: length=20 m; width=2.5 m; gap=0.04 m; allowance=1.15 1; calculation: grout_volume=length*width*gap*allowance=2.3 m^3.","failure":"常見誤解：「注入漿量超過幾何空隙體積就能證明沒有殘留空洞」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Injecting more than the geometric void volume proves that no void remains.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「注漿量與空隙體積」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Grout volume and void account”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b329-v16-09-k1","title":"注漿量與空隙體積","titleEn":"Grout volume and void account","text":"填充空隙所需漿量先由幾何空隙體積估算，再考慮損失與材料體積變化。注入量大不代表填充完整，因為漿液可能沿裂縫流失；壓力、流量與返漿紀錄必須互相對照。","textEn":"Required grout begins with geometric void volume and allowances for loss and volume change. A large injected volume does not prove complete filling because grout can escape through cracks.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：注入漿量超過幾何空隙體積就能證明沒有殘留空洞 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Injecting more than the geometric void volume proves that no void remains. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"關於「注漿量與空隙體積」，下列哪一項敘述正確？","questionEn":"Which statement about \"Grout volume and void account\" is correct?","options":["填充空隙所需漿量先由幾何空隙體積估算，再考慮損失與材料體積變化。","注入漿量超過幾何空隙體積就能證明沒有殘留空洞","施工窗口全長都可以直接乘以施工速度當成可完成量"],"optionsEn":["Required grout begins with geometric void volume and allowances for loss and volume change.","Injecting more than the geometric void volume proves that no void remains.","The entire possession duration can be multiplied by work rate to obtain achievable production."],"answer":0,"explanation":"填充空隙所需漿量先由幾何空隙體積估算，再考慮損失與材料體積變化。 其餘選項是常見誤解。","explanationEn":"Required grout begins with geometric void volume and allowances for loss and volume change. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":9},{"id":"b329-v16-10","title":"注漿量與空隙體積：定量估算","titleEn":"Grout volume and void account: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-09"],"objective":"以數值模型估算「注漿量與空隙體積」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Grout volume and void account” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：length=20 m; width=2.5 m; gap=0.04 m; allowance=1.15 1；計算：grout_volume=length*width*gap*allowance=2.3 m^3。敏感度：gap 單獨增加百分之十至 0.044 m，其餘固定，結果為 2.53 m^3。模型邊界：均勻幾何間隙與假設損失係數；不指定注漿壓力或現地工法。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: length=20 m; width=2.5 m; gap=0.04 m; allowance=1.15 1; calculation: grout_volume=length*width*gap*allowance=2.3 m^3. Sensitivity: gap, increase this input alone by ten percent, to 0.044 m, with all other inputs fixed, gives 2.53 m^3. Model boundary: Uniform geometric gap and assumed loss allowance; no injection pressure or field procedure is specified. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：核對批次體積、流量計及返漿量，將注入壓力與時間曲線同步，完成後以獨立檢測確認空隙分布。","observationEn":"How to cross-check: Reconcile batch volume, flow meter and returns, synchronise injection pressure over time, and verify void distribution afterward using an independent inspection method.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b329-v16-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：length=20 m; width=2.5 m; gap=0.04 m; allowance=1.15 1；計算：grout_volume=length*width*gap*allowance=2.3 m^3。敏感度：gap 單獨增加百分之十至 0.044 m，其餘固定，結果為 2.53 m^3。模型邊界：均勻幾何間隙與假設損失係數；不指定注漿壓力或現地工法。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: length=20 m; width=2.5 m; gap=0.04 m; allowance=1.15 1; calculation: grout_volume=length*width*gap*allowance=2.3 m^3. Sensitivity: gap, increase this input alone by ten percent, to 0.044 m, with all other inputs fixed, gives 2.53 m^3. Model boundary: Uniform geometric gap and assumed loss allowance; no injection pressure or field procedure is specified.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"依「注漿量與空隙體積」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Grout volume and void account\", which statement holds?","options":["風機已經啟動就能證明隧道每一處濃度同樣下降","原創假想算例，全部輸入均非本工程操作參數：length=20 m; width=2.5 m; gap=0.04 m; allowance=1.15 1。","排水管截面夠大就不需要檢查入口堵塞及下游水位"],"optionsEn":["A running fan proves concentration falls equally at every point in the tunnel.","Original hypothetical exercise.","A sufficiently large drain eliminates the need to check blocked inlets and tailwater."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：length=20 m; width=2.5 m; gap=0.04 m; allowance=1.15 1；計算：grout_volume=length*width*gap*allowance=2.3 m^3。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: length=20 m; width=2.5 m; gap=0.04 m; allowance=1.15 1; calculation: grout_volume=length*width*gap*allowance=2.3 m^3. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":10},{"id":"b329-v16-11","title":"注漿量與空隙體積：試驗與驗證","titleEn":"Grout volume and void account: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「注漿量與空隙體積」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Grout volume and void account” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"核對批次體積、流量計及返漿量，將注入壓力與時間曲線同步，完成後以獨立檢測確認空隙分布。 校對泵送流量計與漿液批次密度，分開累計注入、回流及廢棄量，核對薄層幾何尺寸。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Reconcile batch volume, flow meter and returns, synchronise injection pressure over time, and verify void distribution afterward using an independent inspection method. Calibrate pump flow and batch density, separately total injection, return and waste volumes, and verify the thin-layer dimensions. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較正常填充與沿裂縫漏失兩組流量壓力紀錄，做體積收支並提出能辨識兩者的獨立檢測。 再以本單元 gap 的對照值重算 grout_volume，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare flow-pressure records for normal filling and crack leakage, build a volume balance, and propose an independent inspection that distinguishes the two. Also recalculate grout_volume for the alternative gap value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：漏失會讓注入體積增加而空隙仍未填滿，局部封堵又會使壓力快速上升；僅憑達到預算漿量不能驗收。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Loss can increase injected volume while leaving a void unfilled, and local blockage can raise pressure rapidly; reaching the budgeted volume is not acceptance evidence. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b329-v16-11-k1","title":"驗證方法","titleEn":"Verification method","text":"核對批次體積、流量計及返漿量，將注入壓力與時間曲線同步，完成後以獨立檢測確認空隙分布。 校對泵送流量計與漿液批次密度，分開累計注入、回流及廢棄量，核對薄層幾何尺寸。","textEn":"Reconcile batch volume, flow meter and returns, synchronise injection pressure over time, and verify void distribution afterward using an independent inspection method. Calibrate pump flow and batch density, separately total injection, return and waste volumes, and verify the thin-layer dimensions.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-11-k2","title":"現場實務","titleEn":"Site practice","text":"比較正常填充與沿裂縫漏失兩組流量壓力紀錄，做體積收支並提出能辨識兩者的獨立檢測。 再以本單元 gap 的對照值重算 grout_volume，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare flow-pressure records for normal filling and crack leakage, build a volume balance, and propose an independent inspection that distinguishes the two. Also recalculate grout_volume for the alternative gap value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"要驗證「注漿量與空隙體積」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Grout volume and void account\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","兩個七十分貝聲源同時工作一定產生一百四十分貝","核對批次體積、流量計及返漿量，將注入壓力與時間曲線同步，完成後以獨立檢測確認空隙分布。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Two seventy-decibel sources operating together necessarily produce one hundred forty decibels.","Reconcile batch volume, flow meter and returns, synchronise injection pressure over time, and verify void distribution afterward using an independent inspection method."],"answer":2,"explanation":"核對批次體積、流量計及返漿量，將注入壓力與時間曲線同步，完成後以獨立檢測確認空隙分布。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Reconcile batch volume, flow meter and returns, synchronise injection pressure over time, and verify void distribution afterward using an independent inspection method. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":11},{"id":"b329-v16-12","title":"注漿量與空隙體積：失效診斷","titleEn":"Grout volume and void account: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-11"],"objective":"從症狀倒推「注漿量與空隙體積」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Grout volume and void account” and propose discriminating checks, corrective actions and prevention.","instruction":"漏失會讓注入體積增加而空隙仍未填滿，局部封堵又會使壓力快速上升；僅憑達到預算漿量不能驗收。 達到預算漿量不等於填滿空隙，須查回流和漏失。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Loss can increase injected volume while leaving a void unfilled, and local blockage can raise pressure rapidly; reaching the budgeted volume is not acceptance evidence. Reaching the budgeted grout volume does not prove void filling; inspect returns and losses. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：用局部薄層幾何估算漿量，另外記錄超灌與回流來源。","observationEn":"Link to the mechanism: Estimate grout volume from local thin-layer geometry and separately record excess injection and returns.","failure":"誤判風險：若相信「注入漿量超過幾何空隙體積就能證明沒有殘留空洞」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Injecting more than the geometric void volume proves that no void remains.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b329-v16-12-k1","title":"失效模式","titleEn":"Failure mode","text":"漏失會讓注入體積增加而空隙仍未填滿，局部封堵又會使壓力快速上升；僅憑達到預算漿量不能驗收。 達到預算漿量不等於填滿空隙，須查回流和漏失。","textEn":"Loss can increase injected volume while leaving a void unfilled, and local blockage can raise pressure rapidly; reaching the budgeted volume is not acceptance evidence. Reaching the budgeted grout volume does not prove void filling; inspect returns and losses.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"在「注漿量與空隙體積」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Grout volume and void account\" shows distress, which diagnosis is most reasonable?","options":["漏失會讓注入體積增加而空隙仍未填滿，局部封堵又會使壓力快速上升；僅憑達到預算漿量不能驗收。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","施工窗口全長都可以直接乘以施工速度當成可完成量"],"optionsEn":["Loss can increase injected volume while leaving a void unfilled, and local blockage can raise pressure rapidly.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","The entire possession duration can be multiplied by work rate to obtain achievable production."],"answer":0,"explanation":"漏失會讓注入體積增加而空隙仍未填滿，局部封堵又會使壓力快速上升；僅憑達到預算漿量不能驗收。 需以量測區分可能原因。","explanationEn":"Loss can increase injected volume while leaving a void unfilled, and local blockage can raise pressure rapidly; reaching the budgeted volume is not acceptance evidence. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":12},{"id":"b329-v16-13","title":"施工窗口與可完成工作量：機制與系統路徑","titleEn":"Possession window and achievable work: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-12"],"objective":"說明「施工窗口與可完成工作量」如何影響紐約第二大道地鐵一期的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Possession window and achievable work” governs forces, deformation, flow or signals in “Second Avenue Subway Phase 1”, and map the relevant inputs, transfer paths and boundaries.","instruction":"夜間施工窗口需先扣除封鎖確認、隔離、運入及恢復測試時間，剩餘時間才可進行實際工作。提高施工速度不一定提高總產出，若撤場與驗收成為關鍵路徑，必須先調整作業協調。 可施工時間等於總窗口扣掉保護設置、測試及還路等必要活動。這些活動可能有不可重疊的安全依賴；趕工不能直接刪除，應以資源和先後順序改變排程。 把接續工程窗口分成隔離、施工、測試與還路的串聯任務。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「施工窗口與可完成工作量」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A night possession must allow for protection, isolation, access and restoration testing before productive work begins. Higher work rate does not always increase output if clearance and acceptance dominate the critical path. Coordination of dependencies may matter more than nominal production speed. Usable work time equals the possession window minus protection, testing and handback activities. These can have nonoverlapping safety dependencies and cannot simply be deleted to accelerate work. Change scheduling through resources and legitimate task order. Split a connection-work possession into isolation, work, testing and handback tasks. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Possession window and achievable work” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：window=240 min; setup=45 min; restore=55 min; rate=4 m/min；計算：work_length=(window-setup-restore)*rate=560 m。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: window=240 min; setup=45 min; restore=55 min; rate=4 m/min; calculation: work_length=(window-setup-restore)*rate=560 m.","failure":"常見誤解：「施工窗口全長都可以直接乘以施工速度當成可完成量」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The entire possession duration can be multiplied by work rate to obtain achievable production.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「施工窗口與可完成工作量」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Possession window and achievable work”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b329-v16-13-k1","title":"施工窗口與可完成工作量","titleEn":"Possession window and achievable work","text":"夜間施工窗口需先扣除封鎖確認、隔離、運入及恢復測試時間，剩餘時間才可進行實際工作。提高施工速度不一定提高總產出，若撤場與驗收成為關鍵路徑，必須先調整作業協調。","textEn":"A night possession must allow for protection, isolation, access and restoration testing before productive work begins. Higher work rate does not always increase output if clearance and acceptance dominate the critical path.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：施工窗口全長都可以直接乘以施工速度當成可完成量 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The entire possession duration can be multiplied by work rate to obtain achievable production. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"關於「施工窗口與可完成工作量」，下列哪一項敘述正確？","questionEn":"Which statement about \"Possession window and achievable work\" is correct?","options":["施工窗口全長都可以直接乘以施工速度當成可完成量","夜間施工窗口需先扣除封鎖確認、隔離、運入及恢復測試時間，剩餘時間才可進行實際工作。","兩台電扶梯的實際總輸送率必定等於單台額定值兩倍"],"optionsEn":["The entire possession duration can be multiplied by work rate to obtain achievable production.","A night possession must allow for protection, isolation, access and restoration testing before productive work begins.","Two escalators necessarily deliver twice the rated throughput of one escalator."],"answer":1,"explanation":"夜間施工窗口需先扣除封鎖確認、隔離、運入及恢復測試時間，剩餘時間才可進行實際工作。 其餘選項是常見誤解。","explanationEn":"A night possession must allow for protection, isolation, access and restoration testing before productive work begins. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":13},{"id":"b329-v16-14","title":"施工窗口與可完成工作量：定量估算","titleEn":"Possession window and achievable work: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-13"],"objective":"以數值模型估算「施工窗口與可完成工作量」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Possession window and achievable work” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：window=240 min; setup=45 min; restore=55 min; rate=4 m/min；計算：work_length=(window-setup-restore)*rate=560 m。敏感度：setup 單獨增加百分之十至 49.5 min，其餘固定，結果為 542 m。模型邊界：固定速度與確定性窗口；不含返工、設備故障和分段驗收。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: window=240 min; setup=45 min; restore=55 min; rate=4 m/min; calculation: work_length=(window-setup-restore)*rate=560 m. Sensitivity: setup, increase this input alone by ten percent, to 49.5 min, with all other inputs fixed, gives 542 m. Model boundary: Fixed production rate and deterministic window; rework, equipment failure and phased acceptance are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：按事件紀錄封鎖、確認隔離、進場、工作結束與試驗完成時間，用實際有效工作時間計算產率。","observationEn":"How to cross-check: Log possession, isolation confirmation, access, work completion and final testing, then calculate productivity from actual effective work time.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b329-v16-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：window=240 min; setup=45 min; restore=55 min; rate=4 m/min；計算：work_length=(window-setup-restore)*rate=560 m。敏感度：setup 單獨增加百分之十至 49.5 min，其餘固定，結果為 542 m。模型邊界：固定速度與確定性窗口；不含返工、設備故障和分段驗收。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: window=240 min; setup=45 min; restore=55 min; rate=4 m/min; calculation: work_length=(window-setup-restore)*rate=560 m. Sensitivity: setup, increase this input alone by ten percent, to 49.5 min, with all other inputs fixed, gives 542 m. Model boundary: Fixed production rate and deterministic window; rework, equipment failure and phased acceptance are excluded.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"依「施工窗口與可完成工作量」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Possession window and achievable work\", which statement holds?","options":["只要月台平均密度低就不會在任何局部出現壅塞","聯鎖只要正常路徑通過測試就不需要檢查衝突請求","原創假想算例，全部輸入均非本工程操作參數：window=240 min; setup=45 min; restore=55 min; rate=4 m/min。"],"optionsEn":["Low average platform density prevents congestion at every local point.","Passing normal route tests removes the need to test conflicting requests.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：window=240 min; setup=45 min; restore=55 min; rate=4 m/min；計算：work_length=(window-setup-restore)*rate=560 m。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: window=240 min; setup=45 min; restore=55 min; rate=4 m/min; calculation: work_length=(window-setup-restore)*rate=560 m. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":14},{"id":"b329-v16-15","title":"施工窗口與可完成工作量：試驗與驗證","titleEn":"Possession window and achievable work: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「施工窗口與可完成工作量」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Possession window and achievable work” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"按事件紀錄封鎖、確認隔離、進場、工作結束與試驗完成時間，用實際有效工作時間計算產率。 逐項記錄窗口開始、保護完成、施工完成與還路時刻，核對前置條件及實際資源。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Log possession, isolation confirmation, access, work completion and final testing, then calculate productivity from actual effective work time. Log possession start, protection completion, work completion and handback times, checking mandatory prerequisites and resources actually available. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：增加前置作業時間並加入一次返工，重畫關鍵路徑，區分可平行任務與必須完成後才可開放的檢查。 再以本單元 setup 的對照值重算 work_length，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Increase setup time and add one rework event, redraw the critical path, and distinguish parallel tasks from checks that must finish before reopening. Also recalculate work_length for the alternative setup value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：壓縮恢復測試時間可能掩蓋未完成檢查；低估撤場時間會造成延誤，不能把安全確認當成可任意削減的冗餘。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Compressing restoration tests can hide incomplete checks, while underestimated clearance causes delay; safety confirmation cannot be treated as arbitrary slack. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b329-v16-15-k1","title":"驗證方法","titleEn":"Verification method","text":"按事件紀錄封鎖、確認隔離、進場、工作結束與試驗完成時間，用實際有效工作時間計算產率。 逐項記錄窗口開始、保護完成、施工完成與還路時刻，核對前置條件及實際資源。","textEn":"Log possession, isolation confirmation, access, work completion and final testing, then calculate productivity from actual effective work time. Log possession start, protection completion, work completion and handback times, checking mandatory prerequisites and resources actually available.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-15-k2","title":"現場實務","titleEn":"Site practice","text":"增加前置作業時間並加入一次返工，重畫關鍵路徑，區分可平行任務與必須完成後才可開放的檢查。 再以本單元 setup 的對照值重算 work_length，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Increase setup time and add one rework event, redraw the critical path, and distinguish parallel tasks from checks that must finish before reopening. Also recalculate work_length for the alternative setup value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"要驗證「施工窗口與可完成工作量」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Possession window and achievable work\"?","options":["按事件紀錄封鎖、確認隔離、進場、工作結束與試驗完成時間，用實際有效工作時間計算產率。","不確定度太難估計，報告中只寫最佳值即可。","兩台儀器量得同樣座標就證明座標絕對正確"],"optionsEn":["Log possession, isolation confirmation, access, work completion and final testing, then calculate productivity from actual effective work time.","Uncertainty is too hard to estimate, so the report may state only the best value.","Matching coordinates from two instruments prove absolute coordinate accuracy."],"answer":0,"explanation":"按事件紀錄封鎖、確認隔離、進場、工作結束與試驗完成時間，用實際有效工作時間計算產率。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Log possession, isolation confirmation, access, work completion and final testing, then calculate productivity from actual effective work time. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":15},{"id":"b329-v16-16","title":"施工窗口與可完成工作量：失效診斷","titleEn":"Possession window and achievable work: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-15"],"objective":"從症狀倒推「施工窗口與可完成工作量」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Possession window and achievable work” and propose discriminating checks, corrective actions and prevention.","instruction":"壓縮恢復測試時間可能掩蓋未完成檢查；低估撤場時間會造成延誤，不能把安全確認當成可任意削減的冗餘。 施工完成不等於可還路，需保留檢查測試與解除保護時間。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Compressing restoration tests can hide incomplete checks, while underestimated clearance causes delay; safety confirmation cannot be treated as arbitrary slack. Work completion is not readiness for handback; retain inspection, testing and protection-removal time. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：把接續工程窗口分成隔離、施工、測試與還路的串聯任務。","observationEn":"Link to the mechanism: Split a connection-work possession into isolation, work, testing and handback tasks.","failure":"誤判風險：若相信「施工窗口全長都可以直接乘以施工速度當成可完成量」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The entire possession duration can be multiplied by work rate to obtain achievable production.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b329-v16-16-k1","title":"失效模式","titleEn":"Failure mode","text":"壓縮恢復測試時間可能掩蓋未完成檢查；低估撤場時間會造成延誤，不能把安全確認當成可任意削減的冗餘。 施工完成不等於可還路，需保留檢查測試與解除保護時間。","textEn":"Compressing restoration tests can hide incomplete checks, while underestimated clearance causes delay; safety confirmation cannot be treated as arbitrary slack. Work completion is not readiness for handback; retain inspection, testing and protection-removal time.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"在「施工窗口與可完成工作量」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Possession window and achievable work\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","壓縮恢復測試時間可能掩蓋未完成檢查；低估撤場時間會造成延誤，不能把安全確認當成可任意削減的冗餘。","兩台電扶梯的實際總輸送率必定等於單台額定值兩倍"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Compressing restoration tests can hide incomplete checks, while underestimated clearance causes delay; safety confirmation cannot be treated as arbitrary slack.","Two escalators necessarily deliver twice the rated throughput of one escalator."],"answer":1,"explanation":"壓縮恢復測試時間可能掩蓋未完成檢查；低估撤場時間會造成延誤，不能把安全確認當成可任意削減的冗餘。 需以量測區分可能原因。","explanationEn":"Compressing restoration tests can hide incomplete checks, while underestimated clearance causes delay; safety confirmation cannot be treated as arbitrary slack. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":16}],"order":2},{"id":"b329-v16-s3","title":"垂直動線有效輸送率與隧道換氣與稀釋時間","titleEn":"Vertical circulation throughput & Tunnel air exchange and dilution time","description":"本階段聚焦「垂直動線有效輸送率」與「隧道換氣與稀釋時間」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Vertical circulation throughput\" and \"Tunnel air exchange and dilution time\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b329-v16-17","title":"垂直動線有效輸送率：機制與系統路徑","titleEn":"Vertical circulation throughput: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-16"],"objective":"說明「垂直動線有效輸送率」如何影響紐約第二大道地鐵一期的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Vertical circulation throughput” governs forces, deformation, flow or signals in “Second Avenue Subway Phase 1”, and map the relevant inputs, transfer paths and boundaries.","instruction":"電扶梯的理論輸送率可由速度、梯級間距及每級人數估算，實際值還受入口遲疑、行李和站立習慣限制。多台設備不一定能線性相加，因為共用入口或出口可能先形成瓶頸。 階梯間距與速度決定理論階梯通過率，每階占用率則把機械運動轉成載客量。旅客猶豫、行李及出口壅塞會降低實際通過率，不能以理論值直接證明疏散能力。 比較深層站電扶梯和樓梯的服務量及移動時間。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「垂直動線有效輸送率」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Escalator theoretical throughput follows speed, step pitch and occupants per step. Hesitation, luggage and standing habits limit actual use. Several escalators do not necessarily add linearly when a shared entrance or exit becomes the earlier bottleneck. Step pitch and speed determine theoretical step passage, while occupancy per step converts mechanical motion into passenger flow. Hesitation, luggage and blocked exits reduce delivery, so the theoretical rate cannot directly demonstrate evacuation capacity. Compare escalator and stair throughput and travel time at a deep station. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Vertical circulation throughput” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：speed=0.5 m/s; pitch=0.4 m/step; occupants=1.2 persons/step；計算：throughput=3600*speed/pitch*occupants=5400 persons/hour。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: speed=0.5 m/s; pitch=0.4 m/step; occupants=1.2 persons/step; calculation: throughput=3600*speed/pitch*occupants=5400 persons/hour.","failure":"常見誤解：「兩台電扶梯的實際總輸送率必定等於單台額定值兩倍」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Two escalators necessarily deliver twice the rated throughput of one escalator.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「垂直動線有效輸送率」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Vertical circulation throughput”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b329-v16-17-k1","title":"垂直動線有效輸送率","titleEn":"Vertical circulation throughput","text":"電扶梯的理論輸送率可由速度、梯級間距及每級人數估算，實際值還受入口遲疑、行李和站立習慣限制。多台設備不一定能線性相加，因為共用入口或出口可能先形成瓶頸。","textEn":"Escalator theoretical throughput follows speed, step pitch and occupants per step. Hesitation, luggage and standing habits limit actual use.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：兩台電扶梯的實際總輸送率必定等於單台額定值兩倍 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Two escalators necessarily deliver twice the rated throughput of one escalator. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"關於「垂直動線有效輸送率」，下列哪一項敘述正確？","questionEn":"Which statement about \"Vertical circulation throughput\" is correct?","options":["兩台電扶梯的實際總輸送率必定等於單台額定值兩倍","風機已經啟動就能證明隧道每一處濃度同樣下降","電扶梯的理論輸送率可由速度、梯級間距及每級人數估算，實際值還受入口遲疑、行李和站立習慣限制。"],"optionsEn":["Two escalators necessarily deliver twice the rated throughput of one escalator.","A running fan proves concentration falls equally at every point in the tunnel.","Escalator theoretical throughput follows speed, step pitch and occupants per step."],"answer":2,"explanation":"電扶梯的理論輸送率可由速度、梯級間距及每級人數估算，實際值還受入口遲疑、行李和站立習慣限制。 其餘選項是常見誤解。","explanationEn":"Escalator theoretical throughput follows speed, step pitch and occupants per step. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":17},{"id":"b329-v16-18","title":"垂直動線有效輸送率：定量估算","titleEn":"Vertical circulation throughput: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-17"],"objective":"以數值模型估算「垂直動線有效輸送率」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Vertical circulation throughput” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：speed=0.5 m/s; pitch=0.4 m/step; occupants=1.2 persons/step；計算：throughput=3600*speed/pitch*occupants=5400 persons/hour。敏感度：speed 單獨增加百分之十至 0.55 m/s，其餘固定，結果為 5940 persons/hour。模型邊界：穩定速度和平均梯級占用；不含出入口匯流與無障礙替代路徑。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: speed=0.5 m/s; pitch=0.4 m/step; occupants=1.2 persons/step; calculation: throughput=3600*speed/pitch*occupants=5400 persons/hour. Sensitivity: speed, increase this input alone by ten percent, to 0.55 m/s, with all other inputs fixed, gives 5940 persons/hour. Model boundary: Steady speed and mean step occupancy; entrance merging and accessible alternative routes are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：逐時段計數入口和出口，記錄空梯級比例與行李比例，並在共用平台量隊列長度，避免把額定值當現場值。","observationEn":"How to cross-check: Count entrance and exit flow by interval, record empty-step and luggage fractions, and measure the shared-landing queue rather than substituting rated throughput.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b329-v16-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：speed=0.5 m/s; pitch=0.4 m/step; occupants=1.2 persons/step；計算：throughput=3600*speed/pitch*occupants=5400 persons/hour。敏感度：speed 單獨增加百分之十至 0.55 m/s，其餘固定，結果為 5940 persons/hour。模型邊界：穩定速度和平均梯級占用；不含出入口匯流與無障礙替代路徑。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: speed=0.5 m/s; pitch=0.4 m/step; occupants=1.2 persons/step; calculation: throughput=3600*speed/pitch*occupants=5400 persons/hour. Sensitivity: speed, increase this input alone by ten percent, to 0.55 m/s, with all other inputs fixed, gives 5940 persons/hour. Model boundary: Steady speed and mean step occupancy; entrance merging and accessible alternative routes are excluded.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"依「垂直動線有效輸送率」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Vertical circulation throughput\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：speed=0.5 m/s; pitch=0.4 m/step; occupants=1.2 persons/step。","排水管截面夠大就不需要檢查入口堵塞及下游水位","兩個七十分貝聲源同時工作一定產生一百四十分貝"],"optionsEn":["Original hypothetical exercise.","A sufficiently large drain eliminates the need to check blocked inlets and tailwater.","Two seventy-decibel sources operating together necessarily produce one hundred forty decibels."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：speed=0.5 m/s; pitch=0.4 m/step; occupants=1.2 persons/step；計算：throughput=3600*speed/pitch*occupants=5400 persons/hour。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: speed=0.5 m/s; pitch=0.4 m/step; occupants=1.2 persons/step; calculation: throughput=3600*speed/pitch*occupants=5400 persons/hour. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":18},{"id":"b329-v16-19","title":"垂直動線有效輸送率：試驗與驗證","titleEn":"Vertical circulation throughput: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「垂直動線有效輸送率」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Vertical circulation throughput” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"逐時段計數入口和出口，記錄空梯級比例與行李比例，並在共用平台量隊列長度，避免把額定值當現場值。 核對階梯間距與帶速，以入口及出口計數比較乘客流量，另記停頓和空階比例。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Count entrance and exit flow by interval, record empty-step and luggage fractions, and measure the shared-landing queue rather than substituting rated throughput. Verify step pitch and belt speed, compare entry and exit passenger counts, and separately record stoppages and empty-step proportions. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較一台停機與出口縮窄兩種情境，畫出瓶頸位置，提出電梯與樓梯的替代動線並記錄不同旅客所需時間。 再以本單元 speed 的對照值重算 throughput，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare one failed escalator with a narrowed exit, map the bottleneck, and propose lift and stair alternatives while recording journey times for different passenger needs. Also recalculate throughput for the alternative speed value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：出口暫停會造成回堵並影響整段動線；一台設備停機時，另一台的入口可能無法吸收全部轉移人流。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A pause at the exit causes spillback through the circulation path; when one escalator is unavailable, the other entrance may not accept all diverted passengers. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b329-v16-19-k1","title":"驗證方法","titleEn":"Verification method","text":"逐時段計數入口和出口，記錄空梯級比例與行李比例，並在共用平台量隊列長度，避免把額定值當現場值。 核對階梯間距與帶速，以入口及出口計數比較乘客流量，另記停頓和空階比例。","textEn":"Count entrance and exit flow by interval, record empty-step and luggage fractions, and measure the shared-landing queue rather than substituting rated throughput. Verify step pitch and belt speed, compare entry and exit passenger counts, and separately record stoppages and empty-step proportions.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-19-k2","title":"現場實務","titleEn":"Site practice","text":"比較一台停機與出口縮窄兩種情境，畫出瓶頸位置，提出電梯與樓梯的替代動線並記錄不同旅客所需時間。 再以本單元 speed 的對照值重算 throughput，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare one failed escalator with a narrowed exit, map the bottleneck, and propose lift and stair alternatives while recording journey times for different passenger needs. Also recalculate throughput for the alternative speed value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"要驗證「垂直動線有效輸送率」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Vertical circulation throughput\"?","options":["允收準則可以等看到量測數據後再決定。","逐時段計數入口和出口，記錄空梯級比例與行李比例，並在共用平台量隊列長度，避免把額定值當現場值。","兩端高程相同就能證明兩點之間沒有差異沉陷"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Count entrance and exit flow by interval, record empty-step and luggage fractions, and measure the shared-landing queue rather than substituting rated throughput.","Equal endpoint elevations prove there is no differential settlement between them."],"answer":1,"explanation":"逐時段計數入口和出口，記錄空梯級比例與行李比例，並在共用平台量隊列長度，避免把額定值當現場值。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Count entrance and exit flow by interval, record empty-step and luggage fractions, and measure the shared-landing queue rather than substituting rated throughput. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":19},{"id":"b329-v16-20","title":"垂直動線有效輸送率：失效診斷","titleEn":"Vertical circulation throughput: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-19"],"objective":"從症狀倒推「垂直動線有效輸送率」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Vertical circulation throughput” and propose discriminating checks, corrective actions and prevention.","instruction":"出口暫停會造成回堵並影響整段動線；一台設備停機時，另一台的入口可能無法吸收全部轉移人流。 出口堵塞時提高帶速可能加劇累積，需先檢查出口容量。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A pause at the exit causes spillback through the circulation path; when one escalator is unavailable, the other entrance may not accept all diverted passengers. Increasing belt speed can worsen accumulation at a blocked outlet; inspect outlet capacity first. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：比較深層站電扶梯和樓梯的服務量及移動時間。","observationEn":"Link to the mechanism: Compare escalator and stair throughput and travel time at a deep station.","failure":"誤判風險：若相信「兩台電扶梯的實際總輸送率必定等於單台額定值兩倍」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Two escalators necessarily deliver twice the rated throughput of one escalator.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b329-v16-20-k1","title":"失效模式","titleEn":"Failure mode","text":"出口暫停會造成回堵並影響整段動線；一台設備停機時，另一台的入口可能無法吸收全部轉移人流。 出口堵塞時提高帶速可能加劇累積，需先檢查出口容量。","textEn":"A pause at the exit causes spillback through the circulation path; when one escalator is unavailable, the other entrance may not accept all diverted passengers. Increasing belt speed can worsen accumulation at a blocked outlet; inspect outlet capacity first.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"在「垂直動線有效輸送率」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Vertical circulation throughput\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","風機已經啟動就能證明隧道每一處濃度同樣下降","出口暫停會造成回堵並影響整段動線；一台設備停機時，另一台的入口可能無法吸收全部轉移人流。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","A running fan proves concentration falls equally at every point in the tunnel.","A pause at the exit causes spillback through the circulation path; when one escalator is unavailable, the other entrance may not accept all diverted passengers."],"answer":2,"explanation":"出口暫停會造成回堵並影響整段動線；一台設備停機時，另一台的入口可能無法吸收全部轉移人流。 需以量測區分可能原因。","explanationEn":"A pause at the exit causes spillback through the circulation path; when one escalator is unavailable, the other entrance may not accept all diverted passengers. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":20},{"id":"b329-v16-21","title":"隧道換氣與稀釋時間：機制與系統路徑","titleEn":"Tunnel air exchange and dilution time: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-20"],"objective":"說明「隧道換氣與稀釋時間」如何影響紐約第二大道地鐵一期的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Tunnel air exchange and dilution time” governs forces, deformation, flow or signals in “Second Avenue Subway Phase 1”, and map the relevant inputs, transfer paths and boundaries.","instruction":"完全混合空間的濃度在定風量清除下呈指數衰減，體積除以風量給出特徵時間。真實隧道存在分層、死角及列車活塞風，因此這個模型只適合示範稀釋量級，不能直接用作火災避難判定。 完全混合且污染源已停止時，濃度以指數衰減；剩餘比例必須介於零與一。換氣率是流量除以容積，清除時間還依目標濃度而變，不能把一次換氣直接當成全部清除。 建立車站一般換氣量，清楚區別火災煙流分析。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「隧道換氣與稀釋時間」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A perfectly mixed volume under constant clean-air flow exhibits exponential concentration decay, with volume divided by flow as the time constant. Real tunnels contain layering, stagnant regions and train-induced piston flow. This model illustrates dilution scale and cannot establish fire evacuation tenability. For perfect mixing after the source stops, concentration decays exponentially and the remaining fraction lies between zero and one. Air-change rate is flow divided by volume, while clearance time also depends on target concentration. One air change does not mean complete removal. Estimate normal station ventilation while clearly separating fire-smoke analysis. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Tunnel air exchange and dilution time” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=25 m^3/s; remaining=0.1 1；計算：dilution_time=-volume/flow*log(remaining)=276.3102 s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: volume=3000 m^3; flow=25 m^3/s; remaining=0.1 1; calculation: dilution_time=-volume/flow*log(remaining)=276.3102 s.","failure":"常見誤解：「風機已經啟動就能證明隧道每一處濃度同樣下降」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A running fan proves concentration falls equally at every point in the tunnel.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「隧道換氣與稀釋時間」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Tunnel air exchange and dilution time”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b329-v16-21-k1","title":"隧道換氣與稀釋時間","titleEn":"Tunnel air exchange and dilution time","text":"完全混合空間的濃度在定風量清除下呈指數衰減，體積除以風量給出特徵時間。真實隧道存在分層、死角及列車活塞風，因此這個模型只適合示範稀釋量級，不能直接用作火災避難判定。","textEn":"A perfectly mixed volume under constant clean-air flow exhibits exponential concentration decay, with volume divided by flow as the time constant. Real tunnels contain layering, stagnant regions and train-induced piston flow.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：風機已經啟動就能證明隧道每一處濃度同樣下降 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A running fan proves concentration falls equally at every point in the tunnel. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"關於「隧道換氣與稀釋時間」，下列哪一項敘述正確？","questionEn":"Which statement about \"Tunnel air exchange and dilution time\" is correct?","options":["完全混合空間的濃度在定風量清除下呈指數衰減，體積除以風量給出特徵時間。","風機已經啟動就能證明隧道每一處濃度同樣下降","只要月台平均密度低就不會在任何局部出現壅塞"],"optionsEn":["A perfectly mixed volume under constant clean-air flow exhibits exponential concentration decay, with volume divided by flow as the time constant.","A running fan proves concentration falls equally at every point in the tunnel.","Low average platform density prevents congestion at every local point."],"answer":0,"explanation":"完全混合空間的濃度在定風量清除下呈指數衰減，體積除以風量給出特徵時間。 其餘選項是常見誤解。","explanationEn":"A perfectly mixed volume under constant clean-air flow exhibits exponential concentration decay, with volume divided by flow as the time constant. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":21},{"id":"b329-v16-22","title":"隧道換氣與稀釋時間：定量估算","titleEn":"Tunnel air exchange and dilution time: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-21"],"objective":"以數值模型估算「隧道換氣與稀釋時間」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Tunnel air exchange and dilution time” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=25 m^3/s; remaining=0.1 1；計算：dilution_time=-volume/flow*log(remaining)=276.3102 s。敏感度：flow 單獨增加百分之十至 27.5 m^3/s，其餘固定，結果為 251.1911 s。模型邊界：完全混合且污染源已停止；不含煙層、熱浮力與火災成長。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: volume=3000 m^3; flow=25 m^3/s; remaining=0.1 1; calculation: dilution_time=-volume/flow*log(remaining)=276.3102 s. Sensitivity: flow, increase this input alone by ten percent, to 27.5 m^3/s, with all other inputs fixed, gives 251.1911 s. Model boundary: Perfect mixing after source removal; smoke layers, buoyancy and fire growth are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。","observationEn":"How to cross-check: Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b329-v16-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=25 m^3/s; remaining=0.1 1；計算：dilution_time=-volume/flow*log(remaining)=276.3102 s。敏感度：flow 單獨增加百分之十至 27.5 m^3/s，其餘固定，結果為 251.1911 s。模型邊界：完全混合且污染源已停止；不含煙層、熱浮力與火災成長。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: volume=3000 m^3; flow=25 m^3/s; remaining=0.1 1; calculation: dilution_time=-volume/flow*log(remaining)=276.3102 s. Sensitivity: flow, increase this input alone by ten percent, to 27.5 m^3/s, with all other inputs fixed, gives 251.1911 s. Model boundary: Perfect mixing after source removal; smoke layers, buoyancy and fire growth are excluded.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"依「隧道換氣與稀釋時間」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Tunnel air exchange and dilution time\", which statement holds?","options":["聯鎖只要正常路徑通過測試就不需要檢查衝突請求","原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=25 m^3/s; remaining=0.1 1。","兩台儀器量得同樣座標就證明座標絕對正確"],"optionsEn":["Passing normal route tests removes the need to test conflicting requests.","Original hypothetical exercise.","Matching coordinates from two instruments prove absolute coordinate accuracy."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=25 m^3/s; remaining=0.1 1；計算：dilution_time=-volume/flow*log(remaining)=276.3102 s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: volume=3000 m^3; flow=25 m^3/s; remaining=0.1 1; calculation: dilution_time=-volume/flow*log(remaining)=276.3102 s. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":22},{"id":"b329-v16-23","title":"隧道換氣與稀釋時間：試驗與驗證","titleEn":"Tunnel air exchange and dilution time: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「隧道換氣與稀釋時間」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Tunnel air exchange and dilution time” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。 以安全示蹤氣體衰減核對時間常數，多點量測濃度並保留門狀態，檢查是否存在未停止源。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay. Check the time constant with safe tracer decay, measure concentration at multiple points, retain door states, and check for a continuing source. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：對兩種風量計算達到同一殘餘比例的時間，加入一個不完全混合死角，說明量測配置如何發現模型失配。 再以本單元 flow 的對照值重算 dilution_time，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Calculate time to one residual fraction at two airflows, add a poorly mixed pocket, and explain how sensor placement can reveal model mismatch. Also recalculate dilution_time for the alternative flow value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Stagnant pockets may remain concentrated after the average falls; reversed fans or misplaced dampers alter flow paths, so a running-status signal alone cannot verify ventilation. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b329-v16-23-k1","title":"驗證方法","titleEn":"Verification method","text":"用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。 以安全示蹤氣體衰減核對時間常數，多點量測濃度並保留門狀態，檢查是否存在未停止源。","textEn":"Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay. Check the time constant with safe tracer decay, measure concentration at multiple points, retain door states, and check for a continuing source.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-23-k2","title":"現場實務","titleEn":"Site practice","text":"對兩種風量計算達到同一殘餘比例的時間，加入一個不完全混合死角，說明量測配置如何發現模型失配。 再以本單元 flow 的對照值重算 dilution_time，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Calculate time to one residual fraction at two airflows, add a poorly mixed pocket, and explain how sensor placement can reveal model mismatch. Also recalculate dilution_time for the alternative flow value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"要驗證「隧道換氣與稀釋時間」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Tunnel air exchange and dilution time\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","注入漿量超過幾何空隙體積就能證明沒有殘留空洞","用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","Injecting more than the geometric void volume proves that no void remains.","Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay."],"answer":2,"explanation":"用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":23},{"id":"b329-v16-24","title":"隧道換氣與稀釋時間：失效診斷","titleEn":"Tunnel air exchange and dilution time: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-23"],"objective":"從症狀倒推「隧道換氣與稀釋時間」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Tunnel air exchange and dilution time” and propose discriminating checks, corrective actions and prevention.","instruction":"死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。 風機有轉不代表有效稀釋，需查風道旁通和持續污染源。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Stagnant pockets may remain concentrated after the average falls; reversed fans or misplaced dampers alter flow paths, so a running-status signal alone cannot verify ventilation. A running fan does not prove effective dilution; inspect bypass and continuing contaminant sources. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：建立車站一般換氣量，清楚區別火災煙流分析。","observationEn":"Link to the mechanism: Estimate normal station ventilation while clearly separating fire-smoke analysis.","failure":"誤判風險：若相信「風機已經啟動就能證明隧道每一處濃度同樣下降」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A running fan proves concentration falls equally at every point in the tunnel.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b329-v16-24-k1","title":"失效模式","titleEn":"Failure mode","text":"死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。 風機有轉不代表有效稀釋，需查風道旁通和持續污染源。","textEn":"Stagnant pockets may remain concentrated after the average falls; reversed fans or misplaced dampers alter flow paths, so a running-status signal alone cannot verify ventilation. A running fan does not prove effective dilution; inspect bypass and continuing contaminant sources.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"在「隧道換氣與稀釋時間」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Tunnel air exchange and dilution time\" shows distress, which diagnosis is most reasonable?","options":["死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。","只要結構還沒倒，就代表安全餘裕仍然足夠。","只要月台平均密度低就不會在任何局部出現壅塞"],"optionsEn":["Stagnant pockets may remain concentrated after the average falls.","As long as the structure is still standing, its safety margin must still be adequate.","Low average platform density prevents congestion at every local point."],"answer":0,"explanation":"死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。 需以量測區分可能原因。","explanationEn":"Stagnant pockets may remain concentrated after the average falls; reversed fans or misplaced dampers alter flow paths, so a running-status signal alone cannot verify ventilation. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":24}],"order":3},{"id":"b329-v16-s4","title":"月台暫存與隊列守恆與集水與排水容量","titleEn":"Platform storage and queue conservation & Catchment inflow and drainage capacity","description":"本階段聚焦「月台暫存與隊列守恆」與「集水與排水容量」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Platform storage and queue conservation\" and \"Catchment inflow and drainage capacity\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b329-v16-25","title":"月台暫存與隊列守恆：機制與系統路徑","titleEn":"Platform storage and queue conservation: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-24"],"objective":"說明「月台暫存與隊列守恆」如何影響紐約第二大道地鐵一期的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Platform storage and queue conservation” governs forces, deformation, flow or signals in “Second Avenue Subway Phase 1”, and map the relevant inputs, transfer paths and boundaries.","instruction":"月台人數是進入、登車與離開人數的累積差，短時尖峰會使隊列成長，即使全天總運能足夠。可用面積應扣除樓梯口、設備與安全帶；密度只能描述平均狀態，不能單獨代表行人動態風險。 密度是人數除以有效面積，不直接描述人群流速或推擠力。設備、柱子及候車線會減少可用空間；安全通道應另列，不能為了降低平均密度而計入不可占用區域。 把月台候車、行走和設備占用劃成不同有效面積。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「月台暫存與隊列守恆」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Platform population accumulates from arrivals minus boarding and exits. A short surge can grow a queue despite sufficient daily capacity. Usable area excludes stairs, equipment and safety strips. Density describes an average state but does not alone represent dynamic pedestrian risk. Density divides occupancy by usable area but does not directly describe walking speed or crowd pressure. Equipment, columns and waiting boundaries reduce usable space. Reserved circulation must be accounted separately, not included merely to lower the reported average density. Divide platform waiting, movement and equipment occupation into distinct usable areas. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Platform storage and queue conservation” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：people=420 persons; usable_area=350 m^2；計算：density=people/usable_area=1.2 persons/m^2。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: people=420 persons; usable_area=350 m^2; calculation: density=people/usable_area=1.2 persons/m^2.","failure":"常見誤解：「只要月台平均密度低就不會在任何局部出現壅塞」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Low average platform density prevents congestion at every local point.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「月台暫存與隊列守恆」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Platform storage and queue conservation”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b329-v16-25-k1","title":"月台暫存與隊列守恆","titleEn":"Platform storage and queue conservation","text":"月台人數是進入、登車與離開人數的累積差，短時尖峰會使隊列成長，即使全天總運能足夠。可用面積應扣除樓梯口、設備與安全帶；密度只能描述平均狀態，不能單獨代表行人動態風險。","textEn":"Platform population accumulates from arrivals minus boarding and exits. A short surge can grow a queue despite sufficient daily capacity.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要月台平均密度低就不會在任何局部出現壅塞 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Low average platform density prevents congestion at every local point. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"關於「月台暫存與隊列守恆」，下列哪一項敘述正確？","questionEn":"Which statement about \"Platform storage and queue conservation\" is correct?","options":["只要月台平均密度低就不會在任何局部出現壅塞","月台人數是進入、登車與離開人數的累積差，短時尖峰會使隊列成長，即使全天總運能足夠。","排水管截面夠大就不需要檢查入口堵塞及下游水位"],"optionsEn":["Low average platform density prevents congestion at every local point.","Platform population accumulates from arrivals minus boarding and exits.","A sufficiently large drain eliminates the need to check blocked inlets and tailwater."],"answer":1,"explanation":"月台人數是進入、登車與離開人數的累積差，短時尖峰會使隊列成長，即使全天總運能足夠。 其餘選項是常見誤解。","explanationEn":"Platform population accumulates from arrivals minus boarding and exits. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":25},{"id":"b329-v16-26","title":"月台暫存與隊列守恆：定量估算","titleEn":"Platform storage and queue conservation: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-25"],"objective":"以數值模型估算「月台暫存與隊列守恆」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Platform storage and queue conservation” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：people=420 persons; usable_area=350 m^2；計算：density=people/usable_area=1.2 persons/m^2。敏感度：people 將整數計數增加到 463至 463 persons，其餘固定，結果為 1.322857 persons/m^2。模型邊界：均勻平均密度；未含局部擠壓、行李和對向人流。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: people=420 persons; usable_area=350 m^2; calculation: density=people/usable_area=1.2 persons/m^2. Sensitivity: people, increase the integer count to 463, to 463 persons, with all other inputs fixed, gives 1.322857 persons/m^2. Model boundary: Uniform average density; local compression, luggage and opposing streams are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用匿名計數器核對入口、出口與登車量，分區觀察月台密度，保留列車延誤時間以辨認隊列成長來源。","observationEn":"How to cross-check: Reconcile anonymous counts at entrances, exits and train doors, observe density by zone, and retain train-delay times to identify why queues grow.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b329-v16-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：people=420 persons; usable_area=350 m^2；計算：density=people/usable_area=1.2 persons/m^2。敏感度：people 將整數計數增加到 463至 463 persons，其餘固定，結果為 1.322857 persons/m^2。模型邊界：均勻平均密度；未含局部擠壓、行李和對向人流。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: people=420 persons; usable_area=350 m^2; calculation: density=people/usable_area=1.2 persons/m^2. Sensitivity: people, increase the integer count to 463, to 463 persons, with all other inputs fixed, gives 1.322857 persons/m^2. Model boundary: Uniform average density; local compression, luggage and opposing streams are excluded.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"依「月台暫存與隊列守恆」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Platform storage and queue conservation\", which statement holds?","options":["兩個七十分貝聲源同時工作一定產生一百四十分貝","兩端高程相同就能證明兩點之間沒有差異沉陷","原創假想算例，全部輸入均非本工程操作參數：people=420 persons; usable_area=350 m^2。"],"optionsEn":["Two seventy-decibel sources operating together necessarily produce one hundred forty decibels.","Equal endpoint elevations prove there is no differential settlement between them.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：people=420 persons; usable_area=350 m^2；計算：density=people/usable_area=1.2 persons/m^2。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: people=420 persons; usable_area=350 m^2; calculation: density=people/usable_area=1.2 persons/m^2. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":26},{"id":"b329-v16-27","title":"月台暫存與隊列守恆：試驗與驗證","titleEn":"Platform storage and queue conservation: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「月台暫存與隊列守恆」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Platform storage and queue conservation” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用匿名計數器核對入口、出口與登車量，分區觀察月台密度，保留列車延誤時間以辨認隊列成長來源。 以分區影片計數核對總人數，量測淨面積，並同時記錄局部瓶頸及進出流量。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Reconcile anonymous counts at entrances, exits and train doors, observe density by zone, and retain train-delay times to identify why queues grow. Cross-check total occupancy with zonal video counts, measure net area, and record local bottlenecks and entry-exit flows simultaneously. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：模擬一列取消後兩個班距內的人數變化，扣除不能站立的面積，提出分流措施並比較它們改變的是流量還是暫存容量。 再以本單元 people 的對照值重算 density，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Simulate population for two headways after one cancellation, subtract unusable area, and compare whether proposed controls change flow rate or storage capacity. Also recalculate density for the alternative people value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：平均密度低仍可能在樓梯出口形成局部瓶頸；計數器漏記同行群體也會使守恆帳不閉合。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A low mean density can coexist with a bottleneck at a stair exit; missed group entries can also prevent the passenger balance from closing. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b329-v16-27-k1","title":"驗證方法","titleEn":"Verification method","text":"用匿名計數器核對入口、出口與登車量，分區觀察月台密度，保留列車延誤時間以辨認隊列成長來源。 以分區影片計數核對總人數，量測淨面積，並同時記錄局部瓶頸及進出流量。","textEn":"Reconcile anonymous counts at entrances, exits and train doors, observe density by zone, and retain train-delay times to identify why queues grow. Cross-check total occupancy with zonal video counts, measure net area, and record local bottlenecks and entry-exit flows simultaneously.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-27-k2","title":"現場實務","titleEn":"Site practice","text":"模擬一列取消後兩個班距內的人數變化，扣除不能站立的面積，提出分流措施並比較它們改變的是流量還是暫存容量。 再以本單元 people 的對照值重算 density，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Simulate population for two headways after one cancellation, subtract unusable area, and compare whether proposed controls change flow rate or storage capacity. Also recalculate density for the alternative people value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"要驗證「月台暫存與隊列守恆」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Platform storage and queue conservation\"?","options":["用匿名計數器核對入口、出口與登車量，分區觀察月台密度，保留列車延誤時間以辨認隊列成長來源。","量測時不必記錄溫度、速度、運行歷程與施工荷重，因為它們不會影響結果。","施工窗口全長都可以直接乘以施工速度當成可完成量"],"optionsEn":["Reconcile anonymous counts at entrances, exits and train doors, observe density by zone, and retain train-delay times to identify why queues grow.","Temperature, speed, operating history and construction loads need not be recorded because they cannot affect the result.","The entire possession duration can be multiplied by work rate to obtain achievable production."],"answer":0,"explanation":"用匿名計數器核對入口、出口與登車量，分區觀察月台密度，保留列車延誤時間以辨認隊列成長來源。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Reconcile anonymous counts at entrances, exits and train doors, observe density by zone, and retain train-delay times to identify why queues grow. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":27},{"id":"b329-v16-28","title":"月台暫存與隊列守恆：失效診斷","titleEn":"Platform storage and queue conservation: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-27"],"objective":"從症狀倒推「月台暫存與隊列守恆」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Platform storage and queue conservation” and propose discriminating checks, corrective actions and prevention.","instruction":"平均密度低仍可能在樓梯出口形成局部瓶頸；計數器漏記同行群體也會使守恆帳不閉合。 總平均密度低仍可能局部壅塞，須查看門口與樓梯區域。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A low mean density can coexist with a bottleneck at a stair exit; missed group entries can also prevent the passenger balance from closing. Low overall mean density can coexist with local crowding; inspect doorway and stair zones. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：把月台候車、行走和設備占用劃成不同有效面積。","observationEn":"Link to the mechanism: Divide platform waiting, movement and equipment occupation into distinct usable areas.","failure":"誤判風險：若相信「只要月台平均密度低就不會在任何局部出現壅塞」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Low average platform density prevents congestion at every local point.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b329-v16-28-k1","title":"失效模式","titleEn":"Failure mode","text":"平均密度低仍可能在樓梯出口形成局部瓶頸；計數器漏記同行群體也會使守恆帳不閉合。 總平均密度低仍可能局部壅塞，須查看門口與樓梯區域。","textEn":"A low mean density can coexist with a bottleneck at a stair exit; missed group entries can also prevent the passenger balance from closing. Low overall mean density can coexist with local crowding; inspect doorway and stair zones.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"在「月台暫存與隊列守恆」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Platform storage and queue conservation\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","平均密度低仍可能在樓梯出口形成局部瓶頸；計數器漏記同行群體也會使守恆帳不閉合。","排水管截面夠大就不需要檢查入口堵塞及下游水位"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","A low mean density can coexist with a bottleneck at a stair exit; missed group entries can also prevent the passenger balance from closing.","A sufficiently large drain eliminates the need to check blocked inlets and tailwater."],"answer":1,"explanation":"平均密度低仍可能在樓梯出口形成局部瓶頸；計數器漏記同行群體也會使守恆帳不閉合。 需以量測區分可能原因。","explanationEn":"A low mean density can coexist with a bottleneck at a stair exit; missed group entries can also prevent the passenger balance from closing. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":28},{"id":"b329-v16-29","title":"集水與排水容量：機制與系統路徑","titleEn":"Catchment inflow and drainage capacity: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-28"],"objective":"說明「集水與排水容量」如何影響紐約第二大道地鐵一期的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Catchment inflow and drainage capacity” governs forces, deformation, flow or signals in “Second Avenue Subway Phase 1”, and map the relevant inputs, transfer paths and boundaries.","instruction":"短時逕流可先以降雨強度、集水面積和逕流係數估計，但設施排水還受入口阻塞、管線坡度與下游水位影響。鐵路集水範圍若只算軌道面，會漏掉坡面與站區流入。 合理化流量法假定雨強與集流條件相符，面積及逕流係數也須明確。它估算峰值流率而非完整洪水歷線；抽水或蓄水設計還需對時間積分和出口條件。 以入口短時降雨估算排水量，檢查泵浦停止時的積水。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「集水與排水容量」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A first runoff estimate combines rainfall intensity, catchment area and runoff coefficient. Actual drainage also depends on inlet blockage, pipe slope and downstream water level. Counting only track surface can omit inflow from adjacent slopes and station areas. The rational estimate assumes rainfall intensity compatible with catchment response and explicit area and runoff coefficient. It gives a peak rate, not a complete hydrograph. Pumping or storage design additionally requires time integration and outlet conditions. Estimate entrance runoff during a short storm and examine accumulation with the pump stopped. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Catchment inflow and drainage capacity” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2e-05 m/s; area=18000 m^2；計算：flow=coefficient*rain*area=0.306 m^3/s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: coefficient=0.85 1; rain=2e-05 m/s; area=18000 m^2; calculation: flow=coefficient*rain*area=0.306 m^3/s.","failure":"常見誤解：「排水管截面夠大就不需要檢查入口堵塞及下游水位」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A sufficiently large drain eliminates the need to check blocked inlets and tailwater.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「集水與排水容量」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Catchment inflow and drainage capacity”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b329-v16-29-k1","title":"集水與排水容量","titleEn":"Catchment inflow and drainage capacity","text":"短時逕流可先以降雨強度、集水面積和逕流係數估計，但設施排水還受入口阻塞、管線坡度與下游水位影響。鐵路集水範圍若只算軌道面，會漏掉坡面與站區流入。","textEn":"A first runoff estimate combines rainfall intensity, catchment area and runoff coefficient. Actual drainage also depends on inlet blockage, pipe slope and downstream water level.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：排水管截面夠大就不需要檢查入口堵塞及下游水位 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A sufficiently large drain eliminates the need to check blocked inlets and tailwater. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"關於「集水與排水容量」，下列哪一項敘述正確？","questionEn":"Which statement about \"Catchment inflow and drainage capacity\" is correct?","options":["排水管截面夠大就不需要檢查入口堵塞及下游水位","聯鎖只要正常路徑通過測試就不需要檢查衝突請求","短時逕流可先以降雨強度、集水面積和逕流係數估計，但設施排水還受入口阻塞、管線坡度與下游水位影響。"],"optionsEn":["A sufficiently large drain eliminates the need to check blocked inlets and tailwater.","Passing normal route tests removes the need to test conflicting requests.","A first runoff estimate combines rainfall intensity, catchment area and runoff coefficient."],"answer":2,"explanation":"短時逕流可先以降雨強度、集水面積和逕流係數估計，但設施排水還受入口阻塞、管線坡度與下游水位影響。 其餘選項是常見誤解。","explanationEn":"A first runoff estimate combines rainfall intensity, catchment area and runoff coefficient. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":29},{"id":"b329-v16-30","title":"集水與排水容量：定量估算","titleEn":"Catchment inflow and drainage capacity: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-29"],"objective":"以數值模型估算「集水與排水容量」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Catchment inflow and drainage capacity” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2e-05 m/s; area=18000 m^2；計算：flow=coefficient*rain*area=0.306 m^3/s。敏感度：rain 單獨增加百分之十至 2.2e-05 m/s，其餘固定，結果為 0.3366 m^3/s。模型邊界：均勻降雨的合理化法概念；不含集流時間、水文頻率分析或蓄滯。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: coefficient=0.85 1; rain=2e-05 m/s; area=18000 m^2; calculation: flow=coefficient*rain*area=0.306 m^3/s. Sensitivity: rain, increase this input alone by ten percent, to 2.2e-05 m/s, with all other inputs fixed, gives 0.3366 m^3/s. Model boundary: Uniform-rainfall rational-method concept; concentration time, frequency analysis and storage are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。","observationEn":"How to cross-check: Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b329-v16-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2e-05 m/s; area=18000 m^2；計算：flow=coefficient*rain*area=0.306 m^3/s。敏感度：rain 單獨增加百分之十至 2.2e-05 m/s，其餘固定，結果為 0.3366 m^3/s。模型邊界：均勻降雨的合理化法概念；不含集流時間、水文頻率分析或蓄滯。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: coefficient=0.85 1; rain=2e-05 m/s; area=18000 m^2; calculation: flow=coefficient*rain*area=0.306 m^3/s. Sensitivity: rain, increase this input alone by ten percent, to 2.2e-05 m/s, with all other inputs fixed, gives 0.3366 m^3/s. Model boundary: Uniform-rainfall rational-method concept; concentration time, frequency analysis and storage are excluded.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"依「集水與排水容量」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Catchment inflow and drainage capacity\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2e-05 m/s; area=18000 m^2。","兩台儀器量得同樣座標就證明座標絕對正確","注入漿量超過幾何空隙體積就能證明沒有殘留空洞"],"optionsEn":["Original hypothetical exercise.","Matching coordinates from two instruments prove absolute coordinate accuracy.","Injecting more than the geometric void volume proves that no void remains."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2e-05 m/s; area=18000 m^2；計算：flow=coefficient*rain*area=0.306 m^3/s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: coefficient=0.85 1; rain=2e-05 m/s; area=18000 m^2; calculation: flow=coefficient*rain*area=0.306 m^3/s. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":30},{"id":"b329-v16-31","title":"集水與排水容量：試驗與驗證","titleEn":"Catchment inflow and drainage capacity: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「集水與排水容量」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Catchment inflow and drainage capacity” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。 核對雨量單位和有效集水邊界，量測泵浦出流與集水井水位變化，以體積守恆互證。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater. Verify rainfall units and catchment boundaries, measure pump outflow and sump-level change, and cross-check them through volume conservation. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將部分入口視為堵塞，建立地表暫存與排出的水量表；比較增加入口和增加泵量對不同瓶頸的效果。 再以本單元 rain 的對照值重算 flow，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Block selected inlets in the scenario, tabulate surface storage and discharge, and compare additional inlets with additional pumping for different bottlenecks. Also recalculate flow for the alternative rain value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b329-v16-31-k1","title":"驗證方法","titleEn":"Verification method","text":"現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。 核對雨量單位和有效集水邊界，量測泵浦出流與集水井水位變化，以體積守恆互證。","textEn":"Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater. Verify rainfall units and catchment boundaries, measure pump outflow and sump-level change, and cross-check them through volume conservation.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-31-k2","title":"現場實務","titleEn":"Site practice","text":"將部分入口視為堵塞，建立地表暫存與排出的水量表；比較增加入口和增加泵量對不同瓶頸的效果。 再以本單元 rain 的對照值重算 flow，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Block selected inlets in the scenario, tabulate surface storage and discharge, and compare additional inlets with additional pumping for different bottlenecks. Also recalculate flow for the alternative rain value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"要驗證「集水與排水容量」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Catchment inflow and drainage capacity\"?","options":["沿用另一處鐵路設施或路線的量測結果，就可視為本工程已完成驗證。","現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。","兩台電扶梯的實際總輸送率必定等於單台額定值兩倍"],"optionsEn":["Reusing results from another railway facility or route counts as verifying this structure.","Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater.","Two escalators necessarily deliver twice the rated throughput of one escalator."],"answer":1,"explanation":"現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":31},{"id":"b329-v16-32","title":"集水與排水容量：失效診斷","titleEn":"Catchment inflow and drainage capacity: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-31"],"objective":"從症狀倒推「集水與排水容量」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Catchment inflow and drainage capacity” and propose discriminating checks, corrective actions and prevention.","instruction":"垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。 排水堵塞改變有效出流，不能只用較大泵浦銘牌值補償。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause. Blocked drainage changes effective outflow and cannot be compensated merely by a larger pump nameplate rating. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：以入口短時降雨估算排水量，檢查泵浦停止時的積水。","observationEn":"Link to the mechanism: Estimate entrance runoff during a short storm and examine accumulation with the pump stopped.","failure":"誤判風險：若相信「排水管截面夠大就不需要檢查入口堵塞及下游水位」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A sufficiently large drain eliminates the need to check blocked inlets and tailwater.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b329-v16-32-k1","title":"失效模式","titleEn":"Failure mode","text":"垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。 排水堵塞改變有效出流，不能只用較大泵浦銘牌值補償。","textEn":"Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause. Blocked drainage changes effective outflow and cannot be compensated merely by a larger pump nameplate rating.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"在「集水與排水容量」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Catchment inflow and drainage capacity\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","聯鎖只要正常路徑通過測試就不需要檢查衝突請求","垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Passing normal route tests removes the need to test conflicting requests.","Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause."],"answer":2,"explanation":"垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。 需以量測區分可能原因。","explanationEn":"Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":32}],"order":4},{"id":"b329-v16-s5","title":"互斥進路與真值驗證與聲能相加與分貝","titleEn":"Conflicting routes and truth-table verification & Sound-energy addition and decibels","description":"本階段聚焦「互斥進路與真值驗證」與「聲能相加與分貝」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Conflicting routes and truth-table verification\" and \"Sound-energy addition and decibels\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b329-v16-33","title":"互斥進路與真值驗證：機制與系統路徑","titleEn":"Conflicting routes and truth-table verification: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-32"],"objective":"說明「互斥進路與真值驗證」如何影響紐約第二大道地鐵一期的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Conflicting routes and truth-table verification” governs forces, deformation, flow or signals in “Second Avenue Subway Phase 1”, and map the relevant inputs, transfer paths and boundaries.","instruction":"聯鎖的核心是明確禁止衝突進路同時成立，安全條件需要由占用、道岔鎖閉和列車完整通過共同決定。狀態數隨布林輸入快速增加，真值表可檢查邏輯完整性，但不能代替時序與硬體故障分析。 布林組合數表示測試狀態空間的大小，並不代表每個狀態在現場都可達或安全。應把占用、道岔鎖閉和授權的邏輯關係明列，逐項證明危險組合會被拒絕。 為新線接入既有線列出不可同時授權的進路。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「互斥進路與真值驗證」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Interlocking explicitly excludes simultaneous conflicting routes. Occupancy, locked points and complete train passage jointly determine permissive conditions. Boolean input combinations grow rapidly; a truth table checks logical coverage but does not replace timing analysis or hardware fault assessment. The Boolean count describes the size of a test state space, not that every state is reachable or safe in service. Explicitly state relations among occupation, point locking and authority, and demonstrate that hazardous combinations are rejected. List routes that cannot be authorised simultaneously where the new line joins the existing railway. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Conflicting routes and truth-table verification” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：inputs=7 Boolean inputs；計算：combinations=2**inputs=128 states。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: inputs=7 Boolean inputs; calculation: combinations=2**inputs=128 states.","failure":"常見誤解：「聯鎖只要正常路徑通過測試就不需要檢查衝突請求」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Passing normal route tests removes the need to test conflicting requests.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「互斥進路與真值驗證」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Conflicting routes and truth-table verification”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b329-v16-33-k1","title":"互斥進路與真值驗證","titleEn":"Conflicting routes and truth-table verification","text":"聯鎖的核心是明確禁止衝突進路同時成立，安全條件需要由占用、道岔鎖閉和列車完整通過共同決定。狀態數隨布林輸入快速增加，真值表可檢查邏輯完整性，但不能代替時序與硬體故障分析。","textEn":"Interlocking explicitly excludes simultaneous conflicting routes. Occupancy, locked points and complete train passage jointly determine permissive conditions.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：聯鎖只要正常路徑通過測試就不需要檢查衝突請求 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Passing normal route tests removes the need to test conflicting requests. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"關於「互斥進路與真值驗證」，下列哪一項敘述正確？","questionEn":"Which statement about \"Conflicting routes and truth-table verification\" is correct?","options":["聯鎖的核心是明確禁止衝突進路同時成立，安全條件需要由占用、道岔鎖閉和列車完整通過共同決定。","聯鎖只要正常路徑通過測試就不需要檢查衝突請求","兩個七十分貝聲源同時工作一定產生一百四十分貝"],"optionsEn":["Interlocking explicitly excludes simultaneous conflicting routes.","Passing normal route tests removes the need to test conflicting requests.","Two seventy-decibel sources operating together necessarily produce one hundred forty decibels."],"answer":0,"explanation":"聯鎖的核心是明確禁止衝突進路同時成立，安全條件需要由占用、道岔鎖閉和列車完整通過共同決定。 其餘選項是常見誤解。","explanationEn":"Interlocking explicitly excludes simultaneous conflicting routes. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":33},{"id":"b329-v16-34","title":"互斥進路與真值驗證：定量估算","titleEn":"Conflicting routes and truth-table verification: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-33"],"objective":"以數值模型估算「互斥進路與真值驗證」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Conflicting routes and truth-table verification” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：inputs=7 Boolean inputs；計算：combinations=2**inputs=128 states。敏感度：inputs 增加 1 個布林輸入至 8 Boolean inputs，其餘固定，結果為 256 states。模型邊界：有限個獨立二值輸入的完整枚舉；不代表實際聯鎖軟體測試已完成。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: inputs=7 Boolean inputs; calculation: combinations=2**inputs=128 states. Sensitivity: inputs, add one Boolean input, to 8 Boolean inputs, with all other inputs fixed, gives 256 states. Model boundary: Complete enumeration of independent binary inputs; not a claim that real interlocking software has been tested. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：把每個允許輸出對應到必要條件，逐項加入反例測試；再檢查占用訊號失效或道岔未鎖閉時是否回到禁止狀態。","observationEn":"How to cross-check: Map every permissive output to its necessary conditions, add counterexample tests, and check that occupancy failure or unlocked points leads to a restrictive state.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b329-v16-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：inputs=7 Boolean inputs；計算：combinations=2**inputs=128 states。敏感度：inputs 增加 1 個布林輸入至 8 Boolean inputs，其餘固定，結果為 256 states。模型邊界：有限個獨立二值輸入的完整枚舉；不代表實際聯鎖軟體測試已完成。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: inputs=7 Boolean inputs; calculation: combinations=2**inputs=128 states. Sensitivity: inputs, add one Boolean input, to 8 Boolean inputs, with all other inputs fixed, gives 256 states. Model boundary: Complete enumeration of independent binary inputs; not a claim that real interlocking software has been tested.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"依「互斥進路與真值驗證」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Conflicting routes and truth-table verification\", which statement holds?","options":["兩端高程相同就能證明兩點之間沒有差異沉陷","原創假想算例，全部輸入均非本工程操作參數：inputs=7 Boolean inputs。","施工窗口全長都可以直接乘以施工速度當成可完成量"],"optionsEn":["Equal endpoint elevations prove there is no differential settlement between them.","Original hypothetical exercise.","The entire possession duration can be multiplied by work rate to obtain achievable production."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：inputs=7 Boolean inputs；計算：combinations=2**inputs=128 states。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: inputs=7 Boolean inputs; calculation: combinations=2**inputs=128 states. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":34},{"id":"b329-v16-35","title":"互斥進路與真值驗證：試驗與驗證","titleEn":"Conflicting routes and truth-table verification: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「互斥進路與真值驗證」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Conflicting routes and truth-table verification” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"把每個允許輸出對應到必要條件，逐項加入反例測試；再檢查占用訊號失效或道岔未鎖閉時是否回到禁止狀態。 從真值表逐列執行故障注入，記錄預期拒絕與實際輸出，並覆核非法狀態不可授權。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Map every permissive output to its necessary conditions, add counterexample tests, and check that occupancy failure or unlocked points leads to a restrictive state. Execute fault injection row by row from the truth table, recording expected refusal and actual output, and verify that illegal states receive no authority. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：為兩條衝突進路建立真值表，標記禁止組合，再加入先占用後解鎖的事件序列，說明組合邏輯和時序邏輯的差異。 再以本單元 inputs 的對照值重算 combinations，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Build a truth table for two conflicting routes, mark forbidden combinations, then add occupancy and release event sequences to distinguish combinational from temporal logic. Also recalculate combinations for the alternative inputs value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：只測正常進路順序會漏掉同時請求和殘留狀態；感測器卡在允許值也可能使紙上正確的邏輯收到錯誤輸入。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Testing only the normal route sequence misses simultaneous requests and residual states; a sensor stuck permissive can feed wrong inputs to otherwise correct logic. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b329-v16-35-k1","title":"驗證方法","titleEn":"Verification method","text":"把每個允許輸出對應到必要條件，逐項加入反例測試；再檢查占用訊號失效或道岔未鎖閉時是否回到禁止狀態。 從真值表逐列執行故障注入，記錄預期拒絕與實際輸出，並覆核非法狀態不可授權。","textEn":"Map every permissive output to its necessary conditions, add counterexample tests, and check that occupancy failure or unlocked points leads to a restrictive state. Execute fault injection row by row from the truth table, recording expected refusal and actual output, and verify that illegal states receive no authority.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-35-k2","title":"現場實務","titleEn":"Site practice","text":"為兩條衝突進路建立真值表，標記禁止組合，再加入先占用後解鎖的事件序列，說明組合邏輯和時序邏輯的差異。 再以本單元 inputs 的對照值重算 combinations，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Build a truth table for two conflicting routes, mark forbidden combinations, then add occupancy and release event sequences to distinguish combinational from temporal logic. Also recalculate combinations for the alternative inputs value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"要驗證「互斥進路與真值驗證」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Conflicting routes and truth-table verification\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","風機已經啟動就能證明隧道每一處濃度同樣下降","把每個允許輸出對應到必要條件，逐項加入反例測試；再檢查占用訊號失效或道岔未鎖閉時是否回到禁止狀態。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","A running fan proves concentration falls equally at every point in the tunnel.","Map every permissive output to its necessary conditions, add counterexample tests, and check that occupancy failure or unlocked points leads to a restrictive state."],"answer":2,"explanation":"把每個允許輸出對應到必要條件，逐項加入反例測試；再檢查占用訊號失效或道岔未鎖閉時是否回到禁止狀態。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Map every permissive output to its necessary conditions, add counterexample tests, and check that occupancy failure or unlocked points leads to a restrictive state. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":35},{"id":"b329-v16-36","title":"互斥進路與真值驗證：失效診斷","titleEn":"Conflicting routes and truth-table verification: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-35"],"objective":"從症狀倒推「互斥進路與真值驗證」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Conflicting routes and truth-table verification” and propose discriminating checks, corrective actions and prevention.","instruction":"只測正常進路順序會漏掉同時請求和殘留狀態；感測器卡在允許值也可能使紙上正確的邏輯收到錯誤輸入。 狀態覆蓋率高仍可能缺少危險轉移，須查事件先後。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Testing only the normal route sequence misses simultaneous requests and residual states; a sensor stuck permissive can feed wrong inputs to otherwise correct logic. High state coverage can still miss a hazardous transition; inspect event ordering as well. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：為新線接入既有線列出不可同時授權的進路。","observationEn":"Link to the mechanism: List routes that cannot be authorised simultaneously where the new line joins the existing railway.","failure":"誤判風險：若相信「聯鎖只要正常路徑通過測試就不需要檢查衝突請求」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Passing normal route tests removes the need to test conflicting requests.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b329-v16-36-k1","title":"失效模式","titleEn":"Failure mode","text":"只測正常進路順序會漏掉同時請求和殘留狀態；感測器卡在允許值也可能使紙上正確的邏輯收到錯誤輸入。 狀態覆蓋率高仍可能缺少危險轉移，須查事件先後。","textEn":"Testing only the normal route sequence misses simultaneous requests and residual states; a sensor stuck permissive can feed wrong inputs to otherwise correct logic. High state coverage can still miss a hazardous transition; inspect event ordering as well.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"在「互斥進路與真值驗證」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Conflicting routes and truth-table verification\" shows distress, which diagnosis is most reasonable?","options":["只測正常進路順序會漏掉同時請求和殘留狀態；感測器卡在允許值也可能使紙上正確的邏輯收到錯誤輸入。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","兩個七十分貝聲源同時工作一定產生一百四十分貝"],"optionsEn":["Testing only the normal route sequence misses simultaneous requests and residual states.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Two seventy-decibel sources operating together necessarily produce one hundred forty decibels."],"answer":0,"explanation":"只測正常進路順序會漏掉同時請求和殘留狀態；感測器卡在允許值也可能使紙上正確的邏輯收到錯誤輸入。 需以量測區分可能原因。","explanationEn":"Testing only the normal route sequence misses simultaneous requests and residual states; a sensor stuck permissive can feed wrong inputs to otherwise correct logic. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":36},{"id":"b329-v16-37","title":"聲能相加與分貝：機制與系統路徑","titleEn":"Sound-energy addition and decibels: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-36"],"objective":"說明「聲能相加與分貝」如何影響紐約第二大道地鐵一期的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Sound-energy addition and decibels” governs forces, deformation, flow or signals in “Second Avenue Subway Phase 1”, and map the relevant inputs, transfer paths and boundaries.","instruction":"分貝是對數量，兩個聲源不能直接把分貝數字相加。非相干聲源需先還原相對聲能再合成，頻帶、量測位置及時間加權若不同，表面上相同的數值也不能直接比較。 分貝是對數量，聲源互不相干時應先轉回線性能量再相加。頻率加權和量測時間必須相同，否則兩個數字不能直接合成；有相干干涉時還需相位資訊。 將施工和營運聲源分開，以聲能方式計算合成量級。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「聲能相加與分貝」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Decibels are logarithmic, so sound levels cannot be added as ordinary numbers. Incoherent sources must first be converted to relative acoustic energy. Different bands, measurement positions or time weightings prevent direct comparison even when displayed values happen to match. Decibels are logarithmic, so incoherent sources must be converted to linear energy before summation. Frequency weighting and observation duration must match. Coherent interference additionally requires phase information and is not captured by the energy-sum model. Separate construction and operating sources and combine their acoustic energy levels. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Sound-energy addition and decibels” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：L1=73 dB; L2=67 dB；計算：combined=10*log10(10**(L1/10)+10**(L2/10))=73.97323 dB。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: L1=73 dB; L2=67 dB; calculation: combined=10*log10(10**(L1/10)+10**(L2/10))=73.97323 dB.","failure":"常見誤解：「兩個七十分貝聲源同時工作一定產生一百四十分貝」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Two seventy-decibel sources operating together necessarily produce one hundred forty decibels.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「聲能相加與分貝」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Sound-energy addition and decibels”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b329-v16-37-k1","title":"聲能相加與分貝","titleEn":"Sound-energy addition and decibels","text":"分貝是對數量，兩個聲源不能直接把分貝數字相加。非相干聲源需先還原相對聲能再合成，頻帶、量測位置及時間加權若不同，表面上相同的數值也不能直接比較。","textEn":"Decibels are logarithmic, so sound levels cannot be added as ordinary numbers. Incoherent sources must first be converted to relative acoustic energy.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：兩個七十分貝聲源同時工作一定產生一百四十分貝 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Two seventy-decibel sources operating together necessarily produce one hundred forty decibels. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"關於「聲能相加與分貝」，下列哪一項敘述正確？","questionEn":"Which statement about \"Sound-energy addition and decibels\" is correct?","options":["兩個七十分貝聲源同時工作一定產生一百四十分貝","分貝是對數量，兩個聲源不能直接把分貝數字相加。","兩台儀器量得同樣座標就證明座標絕對正確"],"optionsEn":["Two seventy-decibel sources operating together necessarily produce one hundred forty decibels.","Decibels are logarithmic, so sound levels cannot be added as ordinary numbers.","Matching coordinates from two instruments prove absolute coordinate accuracy."],"answer":1,"explanation":"分貝是對數量，兩個聲源不能直接把分貝數字相加。 其餘選項是常見誤解。","explanationEn":"Decibels are logarithmic, so sound levels cannot be added as ordinary numbers. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":37},{"id":"b329-v16-38","title":"聲能相加與分貝：定量估算","titleEn":"Sound-energy addition and decibels: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-37"],"objective":"以數值模型估算「聲能相加與分貝」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Sound-energy addition and decibels” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：L1=73 dB; L2=67 dB；計算：combined=10*log10(10**(L1/10)+10**(L2/10))=73.97323 dB。敏感度：L1 聲級增加 3 dB，不代表數值百分比的功率增加至 76 dB，其餘固定，結果為 76.51497 dB。模型邊界：相同基準與加權的非相干聲源；不含相位干涉與背景扣除。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: L1=73 dB; L2=67 dB; calculation: combined=10*log10(10**(L1/10)+10**(L2/10))=73.97323 dB. Sensitivity: L1, increase the level by 3 dB, not a percentage increase in acoustic power, to 76 dB, with all other inputs fixed, gives 76.51497 dB. Model boundary: Incoherent sources with the same reference and weighting; phase interference and background subtraction are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：同時保留背景、列車通過和設備單獨運轉紀錄，確認麥克風校正、距離與頻帶設定一致，避免把不同時間窗混合。","observationEn":"How to cross-check: Retain background, train-passage and equipment-only recordings, confirm microphone calibration, distance and frequency settings, and avoid mixing incompatible time windows.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b329-v16-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：L1=73 dB; L2=67 dB；計算：combined=10*log10(10**(L1/10)+10**(L2/10))=73.97323 dB。敏感度：L1 聲級增加 3 dB，不代表數值百分比的功率增加至 76 dB，其餘固定，結果為 76.51497 dB。模型邊界：相同基準與加權的非相干聲源；不含相位干涉與背景扣除。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: L1=73 dB; L2=67 dB; calculation: combined=10*log10(10**(L1/10)+10**(L2/10))=73.97323 dB. Sensitivity: L1, increase the level by 3 dB, not a percentage increase in acoustic power, to 76 dB, with all other inputs fixed, gives 76.51497 dB. Model boundary: Incoherent sources with the same reference and weighting; phase interference and background subtraction are excluded.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"依「聲能相加與分貝」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Sound-energy addition and decibels\", which statement holds?","options":["注入漿量超過幾何空隙體積就能證明沒有殘留空洞","兩台電扶梯的實際總輸送率必定等於單台額定值兩倍","原創假想算例，全部輸入均非本工程操作參數：L1=73 dB; L2=67 dB。"],"optionsEn":["Injecting more than the geometric void volume proves that no void remains.","Two escalators necessarily deliver twice the rated throughput of one escalator.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：L1=73 dB; L2=67 dB；計算：combined=10*log10(10**(L1/10)+10**(L2/10))=73.97323 dB。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: L1=73 dB; L2=67 dB; calculation: combined=10*log10(10**(L1/10)+10**(L2/10))=73.97323 dB. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":38},{"id":"b329-v16-39","title":"聲能相加與分貝：試驗與驗證","titleEn":"Sound-energy addition and decibels: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「聲能相加與分貝」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Sound-energy addition and decibels” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"同時保留背景、列車通過和設備單獨運轉紀錄，確認麥克風校正、距離與頻帶設定一致，避免把不同時間窗混合。 以聲級校正器檢查儀器前後漂移，記錄頻率加權和平均時間，再測背景聲單獨量級。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Retain background, train-passage and equipment-only recordings, confirm microphone calibration, distance and frequency settings, and avoid mixing incompatible time windows. Check instrument drift with a sound calibrator before and after measurement, record frequency weighting and averaging time, and measure background separately. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較相同聲級與相差十分貝的兩聲源合成，列出背景扣除的適用條件，並解釋聲壓幅與聲能的對數係數差異。 再以本單元 L1 的對照值重算 combined，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Combine equal-level sources and sources ten decibels apart, list the conditions for background subtraction, and explain the different logarithmic factors for pressure amplitude and energy. Also recalculate combined for the alternative L1 value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：未扣除背景可能高估列車貢獻，錯用算術平均則低估高噪事件；屏障缺口還可能讓局部接收點明顯偏高。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Unremoved background can overstate train contribution, while arithmetic averaging understates loud events; barrier gaps can also produce local receiver hot spots. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b329-v16-39-k1","title":"驗證方法","titleEn":"Verification method","text":"同時保留背景、列車通過和設備單獨運轉紀錄，確認麥克風校正、距離與頻帶設定一致，避免把不同時間窗混合。 以聲級校正器檢查儀器前後漂移，記錄頻率加權和平均時間，再測背景聲單獨量級。","textEn":"Retain background, train-passage and equipment-only recordings, confirm microphone calibration, distance and frequency settings, and avoid mixing incompatible time windows. Check instrument drift with a sound calibrator before and after measurement, record frequency weighting and averaging time, and measure background separately.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-39-k2","title":"現場實務","titleEn":"Site practice","text":"比較相同聲級與相差十分貝的兩聲源合成，列出背景扣除的適用條件，並解釋聲壓幅與聲能的對數係數差異。 再以本單元 L1 的對照值重算 combined，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Combine equal-level sources and sources ten decibels apart, list the conditions for background subtraction, and explain the different logarithmic factors for pressure amplitude and energy. Also recalculate combined for the alternative L1 value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"要驗證「聲能相加與分貝」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Sound-energy addition and decibels\"?","options":["同時保留背景、列車通過和設備單獨運轉紀錄，確認麥克風校正、距離與頻帶設定一致，避免把不同時間窗混合。","不確定度太難估計，報告中只寫最佳值即可。","只要月台平均密度低就不會在任何局部出現壅塞"],"optionsEn":["Retain background, train-passage and equipment-only recordings, confirm microphone calibration, distance and frequency settings, and avoid mixing incompatible time windows.","Uncertainty is too hard to estimate, so the report may state only the best value.","Low average platform density prevents congestion at every local point."],"answer":0,"explanation":"同時保留背景、列車通過和設備單獨運轉紀錄，確認麥克風校正、距離與頻帶設定一致，避免把不同時間窗混合。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Retain background, train-passage and equipment-only recordings, confirm microphone calibration, distance and frequency settings, and avoid mixing incompatible time windows. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":39},{"id":"b329-v16-40","title":"聲能相加與分貝：失效診斷","titleEn":"Sound-energy addition and decibels: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"prerequisiteIds":["b329-v16-39"],"objective":"從症狀倒推「聲能相加與分貝」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Sound-energy addition and decibels” and propose discriminating checks, corrective actions and prevention.","instruction":"未扣除背景可能高估列車貢獻，錯用算術平均則低估高噪事件；屏障缺口還可能讓局部接收點明顯偏高。 若背景聲未扣除，不能把全部合成量歸因於列車。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Unremoved background can overstate train contribution, while arithmetic averaging understates loud events; barrier gaps can also produce local receiver hot spots. Without separate background measurement, the complete combined level cannot be attributed to the train. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：將施工和營運聲源分開，以聲能方式計算合成量級。","observationEn":"Link to the mechanism: Separate construction and operating sources and combine their acoustic energy levels.","failure":"誤判風險：若相信「兩個七十分貝聲源同時工作一定產生一百四十分貝」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Two seventy-decibel sources operating together necessarily produce one hundred forty decibels.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b329-v16-40-k1","title":"失效模式","titleEn":"Failure mode","text":"未扣除背景可能高估列車貢獻，錯用算術平均則低估高噪事件；屏障缺口還可能讓局部接收點明顯偏高。 若背景聲未扣除，不能把全部合成量歸因於列車。","textEn":"Unremoved background can overstate train contribution, while arithmetic averaging understates loud events; barrier gaps can also produce local receiver hot spots. Without separate background measurement, the complete combined level cannot be attributed to the train.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]},{"id":"b329-v16-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"]}],"quiz":{"question":"在「聲能相加與分貝」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Sound-energy addition and decibels\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","未扣除背景可能高估列車貢獻，錯用算術平均則低估高噪事件；屏障缺口還可能讓局部接收點明顯偏高。","兩台儀器量得同樣座標就證明座標絕對正確"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Unremoved background can overstate train contribution, while arithmetic averaging understates loud events.","Matching coordinates from two instruments prove absolute coordinate accuracy."],"answer":1,"explanation":"未扣除背景可能高估列車貢獻，錯用算術平均則低估高噪事件；屏障缺口還可能讓局部接收點明顯偏高。 需以量測區分可能原因。","explanationEn":"Unremoved background can overstate train contribution, while arithmetic averaging understates loud events; barrier gaps can also produce local receiver hot spots. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":40}],"order":5}],"sourceIds":["v16s-b329-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b329-background"],"curriculumVersion":16,"stepCount":40,"estimatedMinutes":1000,"flowDiagram":"assets/diagrams/v16-b329-zh.svg","flowDiagramEn":"assets/diagrams/v16-b329-en.svg"}};
